    /// Rooms from the last online list (empty offline). Free slots are
    /// not listed: the server numbers rooms from the first free slot
    /// (so a real first room is number 0) and marks free slots with
    /// an empty title — filter on both, the data stays unfiltered
    /// upstream. Corroborated against the reference server layout
    /// (`AddRoom` first-free-slot ids, `GetRoomList` empty titles);
    /// the 7.55 display rule itself stays OPEN.
    pub fn set_rooms(&mut self, rooms: Vec<RoomListEntry>) -> &mut Self {
        self.all_rooms = rooms.into_iter().filter(Self::is_listed_room).collect();
        self.room_highlight = 0;
        self.refresh_visible_rooms();
        self
    }

    /// Rebuild the rows the lobby paints and clicks from the wire list
    /// and the active tab, keeping the highlight on a live row.
    fn refresh_visible_rooms(&mut self) {
        let filter = self.room_filter;
        self.rooms = self
            .all_rooms
            .iter()
            .filter(|room| filter.keeps(room))
            .cloned()
            .collect();
        self.room_highlight = self.room_highlight.min(self.rooms.len().saturating_sub(1));
    }

    /// Family named by the active mode tab.
    #[must_use]
    pub fn room_filter(&self) -> RoomListFilter {
        self.room_filter
    }

    /// Room rows currently staged for the Room painter.
    #[must_use]
    pub fn listed_rooms(&self) -> &[RoomListEntry] {
        &self.rooms
    }

    /// Stage one live room row into its numbered slot: replace the
    /// 2003 snapshot of that slot, or insert it in number order. A
    /// 2005 create broadcast fills a slot the snapshot left empty.
    pub fn upsert_room(&mut self, room: RoomListEntry) -> &mut Self {
        if !Self::is_listed_room(&room) {
            return self;
        }
        if let Some(staged) = self
            .all_rooms
            .iter_mut()
            .find(|staged| staged.number == room.number)
        {
            *staged = room;
            self.refresh_visible_rooms();
            return self;
        }
        let insert_at = self
            .all_rooms
            .partition_point(|staged| staged.number < room.number);
        self.all_rooms.insert(insert_at, room);
        self.refresh_visible_rooms();
        self
    }

    /// Drop one live room row from its numbered slot. A 2007 disband
    /// broadcast names the room by number; the highlight stays on a
    /// real row (or at rest when the list becomes empty).
    pub fn remove_room(&mut self, number: i32) -> &mut Self {
        self.all_rooms.retain(|room| room.number != number);
        self.refresh_visible_rooms();
        self
    }

    /// Whether a room-list row names a real room (see [`Self::set_rooms`]).
    fn is_listed_room(room: &RoomListEntry) -> bool {
        room.number != 0 || !room.title.is_empty()
    }

    /// Stage the resident channel id for the waiting header wells.
    /// Called by the session on both boot residency and a resolved
    /// login; the painter adds one for the displayed number.
    pub fn set_waiting_channel_number(&mut self, channel_id: u16) -> &mut Self {
        self.waiting_channel_number = Some(channel_id);
        self
    }

    /// Stage the accepted room number for the waiting header wells.
    /// The 3003 snapshot does not carry it, so the join request owns
    /// this source; `None` until then leaves the wells unpainted.
    pub fn set_waiting_room_number(&mut self, number: i32) -> &mut Self {
        self.waiting_room_number = Some(number);
        self
    }

    /// Channel number staged for the waiting header wells.
    #[must_use]
    pub fn waiting_channel_number(&self) -> Option<u16> {
        self.waiting_channel_number
    }

    /// Room number staged for the waiting header wells.
    #[must_use]
    pub fn waiting_room_number(&self) -> Option<i32> {
        self.waiting_room_number
    }

    /// Remember the joined room; Waiting paints its eight seats, and
    /// the room's arena word sets the Playing backdrop stage (zero or
    /// negative words keep the current stage: the exe replaces a zero
    /// stage on room entry, it never stores one). Joining a new room
    /// clears the chat history and draft: rows come from that room's
    /// 3012/3013 packets only, never carried across rooms.
    pub fn set_joined_room(&mut self, room: JoinedRoom) -> &mut Self {
        if let Some(stage) = arena_stage_word(room.arena) {
            self.arena_stage = stage;
        }
        self.waiting = Some(room);
        self.announced_room_master_id = None;
        self.chat.clear_waiting();
        // A new room means new seats: drop the old per-seat figures,
        // then peers wear their wire equipment as soon as the snapshot
        // lands (no-op without a staged avatar source).
        self.waiting_figures = std::array::from_fn(|_| None);
        self.restage_waiting_figures();
        self
    }

    /// Mark one member's ready flag in place (ready echoes and the
    /// local toggle fold here — never rebuilds the room, so waiting
    /// chat histories survive, unlike [`Self::set_joined_room`]).
    /// Unknown members and no room are silent no-ops.
    pub fn set_member_ready(&mut self, member_id: u8, ready: bool) -> &mut Self {
        if let Some(room) = self.waiting.as_mut() {
            if let Some(slot) = room.slots.iter_mut().find(|slot| slot.index == member_id) {
                if let Some(member) = slot.member.as_mut() {
                    member.ready = ready;
                }
            }
        }
        self
    }

    /// One staged waiting seat's member (`None` for a vacant seat or
    /// without a joined room). Read-only seam for the session's live
    /// join/leave/ready guards; the painter reads the same room state.
    #[must_use]
    pub fn staged_waiting_member(&self, member_id: u8) -> Option<&o2jam_net::RoomMember> {
        self.waiting
            .as_ref()?
            .slots
            .iter()
            .find(|slot| slot.index == member_id)?
            .member
            .as_ref()
    }

    /// Stage one peer into its waiting seat from a 3004 join event.
    /// A previously vacant cover takes the member, and the room's
    /// headcount follows the seats; an existing seat is replaced in
    /// place so chat history and the local seat survive (#379).
    pub fn seat_waiting_member(
        &mut self,
        member_id: u8,
        member: o2jam_net::RoomMember,
    ) -> &mut Self {
        let Some(room) = self.waiting.as_mut() else {
            return self;
        };
        let known_seat = room.slots.iter().any(|slot| slot.index == member_id);
        room.seat_member(member_id, member);
        if known_seat {
            self.restage_waiting_figures();
        }
        self
    }

    /// Clear one peer's waiting seat from a 3007 leave event. The
    /// local seat is never the subject of a leave broadcast (Memoryer
    /// excludes the sender), so only wire peers reach this path.
    pub fn clear_waiting_member_seat(&mut self, member_id: u8) -> &mut Self {
        let Some(room) = self.waiting.as_mut() else {
            return self;
        };
        let known_seat = room.slots.iter().any(|slot| slot.index == member_id);
        room.clear_member(member_id);
        if known_seat {
            self.restage_waiting_figures();
        }
        self
    }

    /// Promote the seat named by a 3007 leave event. The exe marks the
    /// announced master's slot with `+0x30` and clears the others (files
    /// `0x15d888`-`0x15d8d3`); that flag selects START/READY and paints
    /// the seat's master emblem. The local seat id never changes — the
    /// announced id is the second source of the role test.
    pub fn promote_waiting_master(&mut self, member_id: u8) -> &mut Self {
        self.announced_room_master_id = Some(member_id);
        let Some(room) = self.waiting.as_mut() else {
            return self;
        };
        for slot in &mut room.slots {
            if let Some(member) = slot.member.as_mut() {
                member.master = slot.index == member_id;
            }
        }
        self
    }

    /// Fold one member's music state into its waiting seat — the field
    /// the exe keeps at `seat+0x217c` and writes from the `4035`/
    /// `4037` handlers (`docs/music-availability.md` §2).
    ///
    /// The seat keeps the raw wire byte; unknown members and rooms
    /// without the seat stay a silent no-op, exactly like
    /// [`Self::set_member_ready`].
    pub fn set_member_music_state(&mut self, member_id: u8, state: u8) -> &mut Self {
        if let Some(room) = self.waiting.as_mut() {
            if let Some(slot) = room.slots.iter_mut().find(|slot| slot.index == member_id) {
                if let Some(member) = slot.member.as_mut() {
                    member.music_state = state;
                    if state != o2jam_net::MusicState::Downloading.code() {
                        self.member_download_progress[usize::from(member_id)] = None;
                    }
                }
            }
        }
        self
    }

    /// Stage one `4039` percentage for a waiting seat. Unknown seat
    /// indexes are a silent no-op, like every other member mirror.
    pub fn set_member_download_progress(&mut self, member_id: u8, percentage: u8) -> &mut Self {
        if let Some(slot) = self
            .member_download_progress
            .get_mut(usize::from(member_id))
        {
            *slot = Some(percentage);
        }
        self
    }

    /// Staged `4039` percentage of one waiting seat, if the server sent
    /// one since that seat last left the downloading state.
    #[must_use]
    pub fn member_download_progress(&self, member_id: u8) -> Option<u8> {
        self.member_download_progress
            .get(usize::from(member_id))
            .copied()
            .flatten()
    }

    /// Staged music state of one occupied waiting seat (`None` without
    /// a joined room or such a seat): the `seat+0x217c` byte the
    /// `4035`/`4037` family fills (§2).
    #[must_use]
    pub fn member_music_state(&self, member_id: u8) -> Option<u8> {
        let room = self.waiting.as_ref()?;
        let slot = room.slots.iter().find(|slot| slot.index == member_id)?;
        slot.member.as_ref().map(|member| member.music_state)
    }

    /// Toggle-select one waiting team button (the toggle-group map).
    ///
    /// The pressed `TEAMA..H` button maps to its team index with the
    /// shared toggle helper `FUN_0048c810` (file `0x8c810`, REA
    /// `ev_0f6bbde1...`; also the E1 planet-emblem toggle): the helper
    /// lights exactly the pressed button and returns
    /// `pressed - 0x16201004` (team 0..7). The highlight always moves
    /// (`battle_self_team` + the joined room's self team, so the
    /// staged `Wait_Team?.ojs` highlight follows).
    ///
    /// The send follows the dispatch `FUN_004b22d0` (file `0xb22d0`):
    /// the gate helper `FUN_00556680` (file `0x16680`, opcode-id scan)
    /// plus the room-mode bytes (`0x77cd30..32`) decide whether the
    /// press sends. Gated presses only refresh the highlight; ungated
    /// presses queue `SetRoomTeam` 4004 (team index) then `Ready` 4008
    /// (ready cleared on a team switch) for the session bridge.
    ///
    /// OPEN: the handler-table contents behind the gate helper and the
    /// room-mode byte meanings are untraced; the shell treats "no
    /// joined room" as gated (highlight only) and joined as sendable.
    pub fn select_team(&mut self, team: u8) {
        // Toggle-group map (FUN_0048c810): exactly the pressed team
        // lights; the room mirror follows so the staged highlight
        // tracks the selection.
        self.battle_self_team = Some(team);
        if let Some(room) = self.waiting.as_mut() {
            room.team = team;
        }
        // Ungated join sends the pair in exe order (4004 then 4008).
        // Without a joined room there is no send target (gated arm).
        if self.waiting.is_some() {
            self.outbox.pending_room_team = Some(SetRoomTeam { team });
            self.outbox.pending_team_ready = true;
        }
    }
    /// Queued team send for the session bridge, if any (4004). One
    /// take sends once; the next press replaces the queued team.
    pub fn take_room_team(&mut self) -> Option<SetRoomTeam> {
        self.outbox.take_room_team()
    }
