    pub fn arena_stage(&self) -> u16 {
        self.arena_stage
    }

    /// Wire key mode of the joined room (7-key while none is joined):
    /// the Playing art families split members by it
    /// (`avatar::PlayingArtMode`).
    #[must_use]
    pub fn room_key_mode(&self) -> u8 {
        self.waiting
            .as_ref()
            .map_or(o2jam_net::KeyMode::SevenKeys as u8, |room| room.key_mode)
    }

    /// Whether the joined room plays team/versus (`Live`); solo
    /// (`Normal`) otherwise, including while no room is joined.
    #[must_use]
    pub fn room_team_play(&self) -> bool {
        self.waiting
            .as_ref()
            .and_then(|room| o2jam_net::GameMode::from_u8(room.game_mode).ok())
            .is_some_and(|mode| mode == o2jam_net::GameMode::Live)
    }

    /// Self room-master state: the joined room's seat id names our
    /// seat, and seat 0 is the creator — the 4043 header derives the
    /// local `+0x30` flag as 1 exactly when the requesting member id
    /// is 0 (files `0x159bdf`/`0x159c1b`/`0x159c4d`, `docs/relay.md`
    /// §10). The waiting setup swaps START/READY on this flag (file
    /// `0xae38e`: the master arm enables `START 0x16202012` and hides
    /// `READY 0x16202013`; the non-master arm at file `0xae805`
    /// reverses them), and the `MUSELECT 0x16200003` click handler
    /// drops non-master clicks (file `0xb2622`, `je 0xb268d`).
    #[must_use]
    pub fn is_room_master(&self) -> bool {
        self.waiting
            .as_ref()
            .is_some_and(|room| room.member_id == self.announced_room_master_id.unwrap_or(0))
    }

    /// Every occupied peer seat ready: the `START 0x16202012` click
    /// path runs this check (file `0xb5560`) — it skips our own seat
    /// (member id at `0x77cd04`), requires each occupied seat
    /// (`[i + 0x778a16] == 1`) to carry a nonzero ready byte
    /// (`[i * 0x2190 + 0x77eec2]`, slot base `0x77ee90` + `0x32`),
    /// and returns -1 while any occupied peer is unready, so START
    /// errors instead of emitting. Vacant/locked seats (`None`)
    /// never block.
    #[must_use]
    pub fn all_peers_ready(&self) -> bool {
        let Some(room) = self.waiting.as_ref() else {
            return false;
        };
        room.slots.iter().all(|slot| {
            slot.member
                .as_ref()
                .is_none_or(|member| slot.index == room.member_id || member.ready)
        })
    }

    /// The master may start only with every peer ready; non-masters
    /// never start — they ready up (4008, owned by the session
    /// bridge), so their Confirm stays in Waiting.
    #[must_use]
    pub fn can_start_game(&self) -> bool {
        self.is_room_master() && self.all_peers_ready()
    }

    /// The local player's Waiting confirm control shows its armed face —
    /// the exe's per-control press state word (`[ctrl+0x60]`, setter VA
    /// `0x4f72b0`, read back at VA `0x4f72e0`):
    ///
    /// - a guest's READY follows the local seat's ready byte — the
    ///   seat-ready update arms it while the seat is ready and clears it
    ///   with an explicit rest frame when not (VA `0x4b5850`, file
    ///   `0xb590b`-`0xb594f`; VA `0x4af1e0`, file `0xaf2d5`-`0xaf319`);
    /// - a master's START follows the start request the click issued
    ///   ([`Self::arm_waiting_start`]).
    ///
    /// Both arms paint the role-owned body's third record: the exe's
    /// kind-`0x2000` dispatch arm sets absolute frame 3 (file
    /// `0x4f6b7c`). This is the single home for the face state; the
    /// painter reads it as `paint_waiting_scene`'s `confirm_armed`.
    #[must_use]
    pub fn waiting_confirm_armed(&self) -> bool {
        if self.is_room_master() {
            self.waiting_start_armed
        } else {
            self.local_member_ready()
        }
    }

    /// The local player's own seat is marked ready — the exe's self
    /// ready byte (`0x77cd32`), the word the READY face follows.
    #[must_use]
    fn local_member_ready(&self) -> bool {
        let Some(room) = self.waiting.as_ref() else {
            return false;
        };
        room.slots
            .iter()
            .find(|slot| slot.index == room.member_id)
            .and_then(|slot| slot.member.as_ref())
            .is_some_and(|member| member.ready)
    }

    /// Light the START control's armed face: the master's start request
    /// went out and stands until the scene leaves Waiting (the exe arms
    /// it in the click handler, file `0xb237d`, and clears it from its
    /// Waiting update, VA `0x4b2540`). The session bridge calls this
    /// after the 4010 send; the shell's own Confirm never needs it — an
    /// offline master leaves for Loading at once.
    pub fn arm_waiting_start(&mut self) {
        self.waiting_start_armed = true;
    }

    /// Run the waiting Confirm gate shared by Enter and clicks:
    /// slash-free drafts advance offline walkers and masters the START
    /// gate passes ([`Self::press_start`]); guests, unready peers, and a
    /// room song some member lacks stay put.
    fn confirm_waiting(&mut self) {
        if self.take_chat_slash() != SlashCommand::Empty {
            return;
        }
        if self.waiting.is_none() {
            self.enter(Screen::Loading);
            return;
        }
        if self.can_start_game() && self.start_gate_verdict() == StartGateVerdict::Startable {
            self.enter(Screen::Loading);
        }
    }

    /// The START control's press (the exe click handler VA `0x4b22d0`,
    /// `docs/music-availability.md` §4a): arm the face, run the gate, and
    /// answer what the session bridge must send.
    ///
    /// The arms, in the exe's order:
    ///
    /// 1. a download stands (`scene+0x4fc`) — only the face is re-armed,
    ///    no packet;
    /// 2. the gate ([`Self::start_gate_verdict`]) says startable — `4010
    ///    StartGame` (`0xfaa`);
    /// 3. a member lacks the room song — `4034 AcquireMusicRequest`
    ///    (`0xfc2`), which is what makes the server hand the members
    ///    their states and the missing member its download;
    /// 4. a peer is not ready, or the teams do not match — the pinned
    ///    notice and no packet;
    /// 5. a peer cannot access the music, or is already downloading —
    ///    no packet (the exe has no send arm; the player sees the
    ///    download bar, which slice 4 paints).
    pub fn press_start(&mut self) -> StartRequest {
        self.arm_waiting_start();
        if self.music_download.is_running() {
            self.note_waiting_download();
            return StartRequest::Nothing;
        }
        let verdict = self.start_gate_verdict();
        self.waiting_notice = waiting_notice_for(verdict);
        match verdict {
            StartGateVerdict::Startable => StartRequest::StartGame,
            StartGateVerdict::MusicMissing => StartRequest::AcquireMusic,
            StartGateVerdict::PeerNotReady
            | StartGateVerdict::MusicNoAccess
            | StartGateVerdict::MusicDownloading
            | StartGateVerdict::TeamsUnbalanced => StartRequest::Nothing,
        }
    }

    /// The exe's START gate verdict (VA `0x4b5560`, file `0xb5560`),
    /// tested in the exe's order: every occupied peer ready, then team
    /// balance for a room with more than one member, then each occupied
    /// peer's music-state byte (seat `+0x217c`). The local seat is
    /// skipped — the exe's own missing song does not block its click;
    /// the server's 4011 refusal answers it instead.
    ///
    /// No joined room reads [`StartGateVerdict::Startable`]: the offline
    /// walk has no peers to clear.
    #[must_use]
    pub fn start_gate_verdict(&self) -> StartGateVerdict {
        let Some(room) = self.waiting.as_ref() else {
            return StartGateVerdict::Startable;
        };
        let peers: Vec<&o2jam_net::RoomMember> = room
            .slots
            .iter()
            .filter(|slot| slot.index != room.member_id)
            .filter_map(|slot| slot.member.as_ref())
            .collect();
        if peers.iter().any(|peer| !peer.ready) {
            return StartGateVerdict::PeerNotReady;
        }
        if !teams_startable(room.team, &peers) {
            return StartGateVerdict::TeamsUnbalanced;
        }
        peers
            .iter()
            .find_map(|peer| blocked_music_verdict(peer.music_state))
            .unwrap_or(StartGateVerdict::Startable)
    }

    /// The notice standing over the waiting top bar (the exe's notice
    /// box), `None` while nothing was refused.
    #[must_use]
    pub fn waiting_notice(&self) -> Option<&'static str> {
        self.waiting_notice
    }

    /// Clear the standing waiting notice (the session clears it when a
    /// start attempt succeeds).
    pub fn clear_waiting_notice(&mut self) -> &mut Self {
        self.waiting_notice = None;
        self
    }

    /// Stage the room song the 4001 event names (the exe's staged room
    /// song `0x7789d8`, handler VA `0x55f2d0`): the 4025 announcement
    /// and the waiting captions follow it.
    pub fn set_room_music(&mut self, music_id: u16, difficulty: u8, speed: u8) -> &mut Self {
        if let Some(room) = self.waiting.as_mut() {
            room.music_id = music_id;
            room.difficulty = difficulty;
            room.speed = speed;
        }
        self
    }

    /// The room song a 4025 announcement is computed for: the joined
    /// room's staged song, `None` while no room or no song stands
    /// (song id `0` names no chart file).
    #[must_use]
    pub fn room_music_id(&self) -> Option<u16> {
        self.waiting
            .as_ref()
            .map(|room| room.music_id)
            .filter(|music_id| *music_id != 0)
    }

    /// Stage one admitted 4018 row's words for its seat. The exe's
    /// row reader commits only active rows in member range; the
    /// caller owns that admission, so a staged record always has a
    /// real wire row behind it.
    pub fn stage_result_member_record(&mut self, member_id: u8, record: ResultMemberRecord) {
        if let Some(seat) = self.result_member_records.get_mut(usize::from(member_id)) {
            *seat = Some(record);
        }
    }

    /// The joined room's song choice (`None` while no song stands):
    /// the 3003 snapshot shape, kept current by [`Self::set_room_music`]
    /// on 4001 changes. A joined guest that never picks locally uses
    /// this selection to stage the same cover a master's pick stages.
    #[must_use]
    pub fn room_music_selection(&self) -> Option<o2jam_net::SetRoomMusic> {
        let room = self.waiting.as_ref()?;
        (room.music_id != 0).then_some(o2jam_net::SetRoomMusic {
            music_id: room.music_id,
            difficulty: room.difficulty,
            speed: room.speed,
        })
    }

    /// The music state this client announces for one song (§2): `Ready`
    /// when the install's `Music` folder carries the chart file,
    /// `NoMusic` otherwise (the exe's two-way answer, VA `0x4be808`).
    /// Without an install scan there is no local knowledge, so the
    /// answer stays `Ready` — the pre-#276 world, never an invented
    /// refusal.
    #[must_use]
    pub fn music_state_for(&self, song_id: u16) -> MusicState {
        let installed = match self.installed_music.as_ref() {
            None => true,
            Some(seat) => seat.is_installed(song_id),
        };
        MusicState::for_installed(installed)
    }

    /// The staged download queue and its running flag (§4).
    #[must_use]
    pub fn music_download(&self) -> &MusicDownload {
        &self.music_download
    }

    /// Kick the room song's download (the exe's `StartMusicDownload`,
    /// VA `0x4bb1e0`): enqueue it and mark the download running, so a
    /// START press only re-arms the face until the transfer completes.
    /// `true` when the queue took the song; the per-frame transfer
    /// pump fetches it from the configured source (§4).
    pub fn begin_music_download(&mut self, song_id: u16) -> bool {
        let queued = self.music_download.enqueue(song_id);
        if queued {
            self.note_waiting_download();
        }
        queued
    }

    /// Point the download engine at its `Music\` folder and fetch
    /// source. The session uses the install folder; a guard uses a
    /// throwaway pair of folders so no game data is touched.
    pub fn set_music_download_dirs(
        &mut self,
        music_dir: std::path::PathBuf,
        source_dir: Option<std::path::PathBuf>,
    ) -> &mut Self {
        self.music_download.set_transfer_dirs(music_dir, source_dir);
        self
    }

    /// Advance the queued transfers and stage each promoted chart's
    /// availability back into the catalog (§4). The session reports the
    /// returned completions on the wire.
    #[must_use]
    pub fn pump_music_downloads(&mut self) -> Vec<MusicDownloadCompletion> {
        let completions = self.music_download.pump();
        if !completions.is_empty() {
            let music_dir = self.music_download.music_dir().to_path_buf();
            self.set_installed_music(crate::music_install::installed_music_in(&music_dir));
        }
        completions
    }

    /// Stage the download-in-progress notice: a transfer stands (or the
    /// server refused a START because one must), so the waiting top bar
    /// says to wait for it (§4). Slice 4 replaces this with the download
    /// bar the exe paints.
    pub fn note_waiting_download(&mut self) -> &mut Self {
        self.waiting_notice = Some(WAITING_START_DOWNLOAD_NOTICE);
        self
    }

    /// Drop one finished transfer from the queue (the pump owns the
    /// call; the last drop clears the running flag).
    pub fn finish_music_download(&mut self, song_id: u16) -> &mut Self {
        self.music_download.finish(song_id);
        self
    }

    /// Advance a joined guest to Loading on the 4011 start broadcast.
    /// The `START 0x16202012` gate passes masters only (file
    /// `0xb5560`), so a guest Confirm can never satisfy
    /// [`Self::can_start_game`]; the session calls this on 4011
    /// instead of Confirm. Masters never advance here — they keep
    /// the readiness rule through Confirm — and neither do the
    /// offline walk (no joined room), other screens, or a pending
    /// draft (peek-only, so typed text is never eaten). `true`
    /// entered Loading.
    pub fn force_advance_to_loading(&mut self) -> bool {
        if self.flow.current() != Screen::Waiting
            || self.waiting.is_none()
            || self.is_room_master()
            || self.chat_slash_command() != SlashCommand::Empty
        {
            return false;
        }
        self.enter(Screen::Loading);
        true
    }

    /// Native pointer position, when the pointer has moved this run.
    #[must_use]
    pub fn pointer(&self) -> Option<(i32, i32)> {
        self.pointer
    }

    /// Channel row under the pointer, mapped back through the
    /// stored list top (`None` off the rows, off the Channel
    /// screen, under an open side overlay, on the X/scroll chrome, on a
    /// row body, or while a slash draft owns the click).
    #[must_use]
    pub fn hovered_channel_row(&self) -> Option<usize> {
        if self.flow.current() != Screen::Channel || self.side.is_some() {
            return None;
        }
        self.channel_scene.hovered(self.pointer)
    }

    /// Highlighted channel row (the keyboard Confirm target;
    /// `None` off the Channel screen or with no listed rows). The
    /// session bridge logs into it before advancing (ticket #30).
    #[must_use]
    pub fn highlighted_channel(&self) -> Option<ChannelState> {
        if self.flow.current() != Screen::Channel {
            return None;
        }
        self.channel_scene.highlighted()
    }

    /// The one press-kind word for the session gate. Staged rect
    /// readers stay private here (ADR-0003/0013): the game owns the
    /// hit tests, the session owns what the hit means for the wire.
    /// Replaces four separate public queries (#258).
    #[must_use]
    pub fn press_kind_at(&self, x: i32, y: i32) -> PressKind {
        // The fuse's sheet owns the pointer: a click under it never
        // reaches a Room row (the exe's dialog manager consumes it).
        if self.room_no_response_dialog_open() {
            return PressKind::Local;
        }
        match self.flow.current() {
            Screen::Channel => self
                .channel_enter_at(x, y)
                .map_or(PressKind::Local, PressKind::ChannelEnter),
            Screen::Room => self
                .room_entry_at(x, y)
                .map_or(PressKind::Local, |(number, title)| PressKind::RoomRow {
                    number,
                    title,
                }),
            Screen::Waiting if self.waiting_confirm_hit(x, y) => PressKind::WaitingConfirm,
            _ => PressKind::Local,
        }
    }

    /// Channel row whose enter face covers (`x`, `y`) (the mouse
    /// entry target; `None` off the Channel screen, on the X/scroll
    /// chrome, on a row body, or while a slash draft owns the click).
    /// Mirrors [`Self::click_channel_row`]'s enter arm so the session
    /// bridge can exchange the login before forwarding the press
    /// (ticket #30).
    fn channel_enter_at(&self, x: i32, y: i32) -> Option<ChannelState> {
        if self.flow.current() != Screen::Channel {
            return None;
        }
        // The draft stays owned here; the query only peeks at it.
        let draft_busy = self.channel_slash_command() != SlashCommand::Empty;
        self.channel_scene.enter_at(x, y, draft_busy)
    }

    /// Board control under the pointer, through the same staged
    /// resolution the click path rides ([`Self::click_planet`])
    /// (`None` off the board, off the Planet phase, or while a modal
    /// owns the board). Ticket #26 consumes ticket #33's pointer
    /// state here — no second hover store; motion alone arms the
    /// painter's highlight, exactly like the channel select bar.
    #[must_use]
    pub fn hovered_planet_action(&self) -> Option<PlanetAction> {
        if self.flow.current() != Screen::Planet || self.planet_modal().is_some() {
            return None;
        }
        let (x, y) = self.pointer?;
        let placements: &[ScenePlacement] = self
            .scene_art(Screen::Planet)
            .map_or(&[], |art| &art.placements);
        planet_action_at(placements, x, y)
    }

    /// Shelf cell under the pointer on the open Item Shop side.
    /// Motion alone arms the white tooltip; the row-pick and button
    /// hover frames in the A/B sweep show no tooltip there
    /// (`05b24e64…` entry, `hover-shelf-figure1` / `hover-shelf-row1-buy`).
    /// The geometry rides the staged ITEMSHOW rects, never a literal.
    #[must_use]
    pub fn hovered_item_show_slot(&self) -> Option<usize> {
        if self.side != Some(SideScreen::Shop) {
            return None;
        }
        let (x, y) = self.pointer?;
        self.side_placements
            .iter()
            .enumerate()
            .find(|(_, placed)| {
                placed
                    .code
                    .checked_sub(SHOP_ITEMSHOW_FIRST_CODE)
                    .is_some_and(|slot| {
                        slot < SHOP_ITEM_ROWS as u32 && rect_hit(&placed.rect, x, y)
                    })
            })
            .map(|(index, _)| index)
    }

    /// Channel dialog click: the scene resolves the X close, the
    /// scroll arrows, the row highlight, and the enter-face target
    /// (#259). This seam still owns the flow steps and the shared
    /// slash draft: a face click landing while a draft holds it is
    /// reported back so the draft is consumed exactly once.
    fn click_channel_row(&mut self, x: i32, y: i32) {
        let draft_busy = self.channel_slash_command() != SlashCommand::Empty;
        match self.channel_scene.press(x, y, draft_busy) {
            // X/BACK and the row enter face are producer branches: the
            // exe cues id 0x23 before the close and id 9 before the
            // join post (VA `0x48ff45` / `0x47530d`).
            ChannelPress::Close => {
                self.cue_ui_effect(UiEffectId::ChannelExit);
                self.enter(Screen::Planet);
            }
            ChannelPress::Enter => {
                self.cue_ui_effect(UiEffectId::ChannelRowJoin);
                self.enter(Screen::Room);
            }
            ChannelPress::ConsumeDraft => {
                let _ = self.take_channel_slash();
            }
            ChannelPress::Noop => {}
        }
    }

    /// Room click: a staged chrome button first ([`Self::click_room_control`]),
    /// then the row hit test — staged panels (verbatim `.bnd` rects in
    /// file order) ahead of the legacy row bands. Either row path
    /// highlights the row and advances like Confirm.
    /// Leave the channel lobby for the channel list: the local scene
    /// step plus the pinned wire leave (`ChannelLogout` 2021, empty —
    /// the exe's exit dispatch sends it, ticket #175 pin; Memoryer
    /// stonewalls the next 1004 until it lands). The session bridge
    /// drains the queue; the offline walk drains nowhere, like the
    /// result outbox.
    fn exit_room_to_channel(&mut self) {
        self.outbox.pending_channel_logout = true;
        self.enter(Screen::Channel);
    }

    fn click_room_row(&mut self, x: i32, y: i32) {
        if self.click_room_control(x, y) {
            return;
        }
        let Some(index) = self.room_index_at(x, y) else {
            return;
        };
        self.room_highlight = index;
        // Locked rooms gate through the password dialog (lifecycle §7:
        // `DIALOG_INPUTPASSWORD` `CDInputPassword`); unlocked rows join
        // straight to Waiting.
        if let Some(room) = self.rooms.get(index) {
            if room.has_password {
                if self.password_art.is_some() {
                    self.open_password_dialog(room.number);
                } else {
                    self.last_room_control_noop = Some(RoomControlNoop {
                        id: "LOCKED_ROOM_ROW",
                        next_step: DIALOG_STAGE_STEP,
                    });
                }
                return;
            }
        }
        self.enter(Screen::Waiting);
    }

    /// Answer the staged room chrome control under the click (tickets
    /// #32/#34): the behaviour comes from [`ROOM_CONTROLS`], and a
    /// control with no evidenced target still records its press instead
    /// of dropping it silently. `true` consumed the click, so the room
    /// row hit test never sees a button press.
    fn click_room_control(&mut self, x: i32, y: i32) -> bool {
        let Some(control) = self.room_control_at(x, y) else {
            return false;
        };
        match control.action {
            // Leave for the channel scene (lifecycle §7: the same edge
            // the Back key rides), telling the server (pinned 2021).
            RoomControlAction::Back => self.exit_room_to_channel(),
            // Open the create-room dialog (lifecycle §7:
            // `DIALOG_CREATEROOM` `CDCreateRoom`); without the staged
            // sheet the modal would own input it cannot paint, so the
            // click records a noop and the lobby stays usable.
            RoomControlAction::Create => {
                if self.create_room_art.is_some() {
                    self.open_create_room_dialog();
                } else {
                    self.last_room_control_noop = Some(RoomControlNoop {
                        id: "IDC_BUTTON_SROOM_CREATE",
                        next_step: DIALOG_STAGE_STEP,
                    });
                }
            }
            // Open the options dialog over the lobby (the same
            // `Dialog_Option_*` sheet the Planet gear mounts:
            // EXIT/Escape closes it back onto Room, the flow never
            // moves).
            RoomControlAction::Options => self.planet_board.open_modal(PlanetModal::Options),
            // Visit a side screen the tree already ships; the lobby
            // gate is `can_visit_side`.
            RoomControlAction::Side(side) => {
                self.visit_side(side);
            }
            // Room control `0x13200032` follows the exe chain
            // `0x4902bb` → `0x495110` → `ChangeState(0xb)`: set the
            // pinned tutorial globals before entering the side state,
            // never on a rejected visit. Geometry is the staged rect.
            RoomControlAction::RoomFilter(filter) => {
                self.room_filter = filter;
                self.refresh_visible_rooms();
                // The staged tab changed the local family; the wire half
                // stays a labeled no-op until a 2002 body pins it.
                self.last_room_control_noop = Some(RoomControlNoop {
                    id: control.id,
                    next_step: ROOM_FILTER_SEND_STEP,
                });
            }
            RoomControlAction::TutorialEntry => {
                if self.visit_side(SideScreen::Tutorial) {
                    self.tutorial_chart_globals = Some(TUTORIAL_CHART_GLOBALS);
                }
            }
            // No evidenced target: record the press and its next
            // evidence step — never a silent drop.
            RoomControlAction::Unwired { next_step } => {
                tracing::debug!(
                    control = control.id,
                    code = format_args!("0x{:08X}", control.code),
                    next_step,
                    "room control has no evidenced behaviour yet; press recorded"
                );
                self.last_room_control_noop = Some(RoomControlNoop {
                    id: control.id,
                    next_step,
                });
            }
        }
        true
    }

    /// Staged room chrome control under the click, if the table names
    /// its code. Geometry comes from the parsed staged rect only (owner
    /// rule `f38f3`). The exe-hidden bundled chrome never answers:
    /// `MYCAPSULE`/`EVENT`/`MYBAND` clear their draw-path words on room
    /// setup (`room_chrome_visible`), so hover resolves through this
    /// same gate.
    ///
    /// Not listed: the row templates (`IDC_BUTTON_SROOM_EXBUTTON1..6`,
    /// the `SET` clone parents) whose rects ARE the room rows and
    /// therefore fall through to the row hit test — EXE-static by
    /// negative evidence (0 changed px on all six panels,
    /// `docs/hover.md`), so the hover resolver below never names
    /// them either.
    fn room_control_at(&self, x: i32, y: i32) -> Option<&'static RoomControl> {
        let placements = &self.scene_art(Screen::Room)?.placements;
        ROOM_CONTROLS.iter().find(|control| {
            room_chrome_visible(control.code) && staged_code_hit(placements, control.code, x, y)
        })
    }

    /// Staged room chrome control under the pointer (`None` off every
    /// control, off the Room Scene, or while a dialog, modal, or side
    /// Scene covers the lobby — clicks route to those layers first,
    /// so hover follows). The shared hover source ticket #26 consumes
    /// for the planet board is the pointer itself (the snapshot pointer);
    /// this resolver maps it onto the room chrome the same way clicks
    /// resolve (`staged_code_hit` on the parsed rects). Row panels
    /// (`EXBUTTON1..6`) are not chrome controls: the pointer over a
    /// panel resolves to nothing and repaints nothing — EXE-static by
    /// negative evidence (`docs/hover.md`: 0 changed px, no
    /// `Room_MOver.ojs` overlay in either state).
    fn hovered_room_control(&self) -> Option<&'static RoomControl> {
        if self.flow.current() != Screen::Room {
            return None;
        }
        if self.room_dialog.is_some() || self.planet_modal().is_some() || self.side.is_some() {
            return None;
        }
        let (x, y) = self.pointer?;
        let control = self.room_control_at(x, y)?;
        // Active filter/tab already shows frame 1 and never changes on
        // hover (EXE-pinned no-change, `docs/hover.md`), so hovering
        // one resolves to nothing: the hover must not repaint frame 1
        // with frame 0. Filter/tab switching is unwired, so the
        // default-active pair below never moves in the shell.
        let tab_code = match self.room_filter {
            RoomListFilter::All => 0x1320_1003,
            RoomListFilter::Normal => 0x1320_1004,
            RoomListFilter::Live => 0x1320_1005,
        };
        (control.code != tab_code && !ROOM_ACTIVE_CHROME_CODES.contains(&control.code))
            .then_some(control)
    }

    /// Room-row index under a click, staged panels first (see
    /// [`Self::click_room_row`]).
    fn room_index_at(&self, x: i32, y: i32) -> Option<usize> {
        let staged = self.room_panel_click(x, y);
        let band = || list_row_hit(CLICK_W, CLICK_H, self.rooms.len(), x, y);
        staged
            .or_else(band)
            .filter(|index| *index < self.rooms.len())
    }

    /// Room entry under a click: number and title from one hit test
    /// (the number to join, the title for the resident heuristic —
    /// the joined snapshot carries no wire room id, ticket #231).
    /// The session press module is the only caller; both queries
    /// used to be separate public gates over the same row.
    fn room_entry_at(&self, x: i32, y: i32) -> Option<(i32, String)> {
        let room = self.rooms.get(self.room_index_at(x, y)?)?;
        Some((room.number, room.title.clone()))
    }

    /// Staged room-panel click: file-order panel index covering
    /// (`x`, `y`) (`None` while no bound panel covers the point).
    fn room_panel_click(&self, x: i32, y: i32) -> Option<usize> {
        let placements = &self.scene_art(Screen::Room)?.placements;
        if !has_room_panels(placements) {
            return None;
        }
        room_panel_hit(placements, x, y)
    }

    /// Staged room panel under the pointer, when no dialog, modal, or
    /// side view owns input. The same rect hit test as a click, but
    /// only a listed room makes the row template live (the empty-list
    /// hover sweep pinned no panel overlay, `docs/hover.md`).
    fn hovered_room_panel(&self) -> Option<usize> {
        if self.flow.current() != Screen::Room
            || self.rooms.is_empty()
            || self.room_dialog.is_some()
            || self.planet_modal().is_some()
            || self.side.is_some()
        {
            return None;
        }
        let (x, y) = self.pointer?;
        self.room_panel_click(x, y)
    }

    /// `SetRoomMusic` body behind one dialog row: the row's song id
    /// plus its difficulty slot (row slots repeat Easy/Normal/Hard,
    /// the `Difficulty` code order), at the surviving speed. `None`
    /// when the chart is not playable, the slot code, the song id, or
    /// the speed has no source — nothing is invented.
    fn select_row_pick(&self, row: SelectMusicRow<'_>) -> Option<SetRoomMusic> {
        // §3: the exe sends `4000` only for a row whose chart bit is
        // set, and its confirm handlers refuse a song whose
        // `o2ma<id>.ojn` is missing (§2). No chart bit, no pick.
        if !row.playable() {
            return None;
        }
        let difficulty = u8::try_from(row.slot).ok()?;
        Difficulty::from_code(difficulty)?;
        Some(SetRoomMusic {
            music_id: u16::try_from(row.song.song_id).ok()?,
            difficulty,
            speed: self.staged_pick_speed()?,
        })
    }
    /// Speed surviving a dialog pick: the staged selection's speed
    /// first, else the joined room's. `None` with no source.
    fn staged_pick_speed(&self) -> Option<u8> {
        self.selected_music
            .map(|selection| selection.speed)
            .or_else(|| self.waiting.as_ref().map(|room| room.speed))
    }
    /// Commit one dialog row as the room song: the room state takes
    /// the pick at once (title/speed captions repaint) and the 4000
    /// body queues for the session bridge. `false` stages nothing
    /// (no joined room to commit to). The no-catalog path stays
    /// display-only — empty rows never invent a song.
    ///
    /// A row whose chart file the install lacks is refused: the exe's
    /// confirm path sets the not-downloaded caption on the shared
    /// notice dialog and sends no `4000` (§3). This swaps the dialog's
    /// status line for [`SELECT_NOT_DOWNLOADED_NOTICE`] and stages
    /// nothing else; the Download icon the caption names is a later
    /// slice, so a refused row never becomes a pick.
    fn pick_select_music_row(&mut self, index: usize) -> bool {
        if self.waiting.is_none() {
            return false;
        }
        let row = self.select_rows().get(index).copied();
        let Some(row) = row else {
            return false;
        };
        if !row.song.installed {
            self.select_music_notice = Some(SELECT_NOT_DOWNLOADED_NOTICE);
            return true;
        }
        let Some(pick) = self.select_row_pick(row) else {
            return false;
        };
        self.select_music_notice = None;
        self.set_selected_music(pick);
        self.outbox.pending_music_send = Some(pick);
        true
    }
    /// Song-dialog click: a search-table row hit commits the row's
    /// song through [`Self::pick_select_music_row`]. Only the room
    /// master sees the dialog (paint gates it) and only masters pick
    /// — the `MUSELECT 0x16200003` click handler drops non-master
    /// clicks (file `0xb2622`). The filter columns (#273), OK (#232),
    /// mode switch, help sheets, pager and search (#285,
    /// [`Self::click_select_chrome`]) each answer on their staged
    /// `.bnd` rect; other chrome stays display-only and BACK stays
    /// reachable. `true` consumed.
    fn click_select_music(&mut self, x: i32, y: i32) -> bool {
        if !self.is_room_master() || self.select_music_art.is_none() {
            return false;
        }
        let rows = self.select_rows();
        if let Some(index) = select_row_hit(x, y, rows.len()) {
            let page_row = self.select_page.saturating_mul(SELECT_VISIBLE_ROWS);
            return self.pick_select_music_row(page_row.saturating_add(index));
        }
        // Dialog OK confirms the staged pick (ticket #232): the
        // BND-paired OK button (Dialog_SelectMusic.bnd rect [1])
        // closes the dialog with the pick queued for the session
        // bridge. A "staged pick" is a queued `pending_music_send`
        // (row click), not the pre-existing room song, so OK with
        // no row click stays a no-op like the other chrome and the
        // click falls through.
        if let Some(art) = self.select_music_art.as_ref() {
            if staged_rect_hit(&art.placements, "IDC_BUTTON_DSMUSIC_OK", x, y)
                && self.has_pending_music_send()
            {
                self.select_music_art = None;
                self.select_music_notice = None;
                return true;
            }
        }
        if self.click_select_chrome(x, y) {
            return true;
        }
        self.click_select_filter(x, y)
    }

    /// Search-result rows the dialog currently shows: the three
    /// filter columns first (#273), then the submitted search query
    /// (#285). Typing alone never narrows the table — the SERACH
    /// button submits the draft, as in the exe's search arm.
    fn select_rows(&self) -> Vec<SelectMusicRow<'_>> {
        let rows = select_music_rows(&self.catalog_songs, self.select_filter);
        let Some((field, query)) = self.select_search_query.as_ref() else {
            return rows;
        };
        if query.trim().is_empty() {
            return rows;
        }
        let needle = query.trim().to_lowercase();
        rows.into_iter()
            .filter(|row| {
                let text = match field {
                    SelectSearchField::Title => &row.song.title,
                    SelectSearchField::Artist => &row.song.artist,
                };
                text.to_lowercase().contains(&needle)
            })
            .collect()
    }

    /// Chrome actions of the song dialog (#285, `docs/select-chrome.md`).
    /// Every hit test reads a staged `.bnd` rect, never a literal.
    /// `true` consumed.
    fn click_select_chrome(&mut self, x: i32, y: i32) -> bool {
        let Some(action) = self
            .select_music_art
            .as_ref()
            .and_then(|art| select_chrome_action_at(&art.placements, x, y))
        else {
            return false;
        };
        match action {
            SelectChromeAction::Mode(mode) => {
                self.select_mode = mode;
                self.select_help = SelectHelpSheet::None;
            }
            SelectChromeAction::Help(sheet) => self.select_help = sheet,
            SelectChromeAction::Reorder(_) => {
                // Exe arms VA `0x43e8bd`/`0x43e8f9` reorder a *playlist*
                // row; the result tab disables both buttons (VA
                // `0x43e52d`/`0x43e550`), which is the tab we stage.
            }
            SelectChromeAction::Page(step) => {
                let pages = self
                    .select_rows()
                    .len()
                    .div_ceil(SELECT_VISIBLE_ROWS)
                    .max(1);
                self.select_page = match step {
                    SelectPagerStep::Previous => self.select_page.saturating_sub(1),
                    SelectPagerStep::Next => (self.select_page + 1).min(pages - 1),
                };
            }
            SelectChromeAction::SearchField(field) => self.select_search_field = field,
            SelectChromeAction::Search => {
                let query = self.select_search_draft.trim().to_owned();
                self.select_search_query =
                    (!query.is_empty()).then_some((self.select_search_field, query));
                self.select_page = 0;
            }
            SelectChromeAction::SearchIndex(_index) => {
                // Chosung key grid: the `+0x680` keyed filter rebuild
                // (VA `0x444630`, key names at VA `0x6454d8`) is its own
                // slice; the inventory pins every button in
                // `docs/select-chrome.md`. No invented key here.
                return false;
            }
        }
        true
    }

    /// Song-dialog filter columns (ticket #273): a click on a
    /// `IDC_BUTTON_DSMUSIC_STEP{1,2,3}_*` button stores that column's
    /// choice and the table narrows on the next paint. The exe does the
    /// same — the click handlers store `code - base` in the dialog
    /// state word (level VA `0x43f6c2`, label VA `0x43f7ee`, genre VA
    /// `0x43f91b`) and rerun the filter chain at once (VA `0x446950`).
    /// `true` consumed.
    fn click_select_filter(&mut self, x: i32, y: i32) -> bool {
        let Some(art) = self.select_music_art.as_ref() else {
            return false;
        };
        let Some(choice) = select_filter_choice_at(&art.placements, x, y) else {
            return false;
        };
        self.select_filter.choose(choice);
        true
    }

    /// Live filter-column choices of the song dialog (the search table
    /// narrows by them).
    #[must_use]
    pub fn select_filter(&self) -> SelectMusicFilter {
        self.select_filter
    }

    /// Live selection panel (`SongSelect` on open).
    #[must_use]
    pub fn select_mode(&self) -> SelectMusicMode {
        self.select_mode
    }

    /// Help sheet currently painted (`None` on open).
    #[must_use]
    pub fn select_help_sheet(&self) -> SelectHelpSheet {
        self.select_help
    }

    /// Zero-based result page the pager shows.
    #[must_use]
    pub fn select_page(&self) -> usize {
        self.select_page
    }

    /// Column the next SERACH press applies to.
    #[must_use]
    pub fn select_search_field(&self) -> SelectSearchField {
        self.select_search_field
    }

    /// Text currently in the dialog's search edit box.
    #[must_use]
    pub fn select_search_draft(&self) -> &str {
        &self.select_search_draft
    }

    /// Append one typed character to the dialog's search edit box.
    /// The open dialog owns keyboard text; chat waits until it closes.
    pub fn push_select_search_char(&mut self, typed: char) {
        if !typed.is_control() {
            self.select_search_draft.push(typed);
        }
    }

    /// Erase the last search-draft character (Backspace).
    pub fn delete_select_search_char(&mut self) {
        self.select_search_draft.pop();
    }
    /// Whether a click hits a staged Waiting confirm button
    /// (START/READY ids only; art-less clicks land nowhere — no pinned
    /// fallback geometry names these buttons). The session bridge runs
    /// its networked Confirm gate on a hit instead of the local one.
    #[must_use]
    fn waiting_confirm_hit(&self, x: i32, y: i32) -> bool {
        let Some(art) = self.scene_art(Screen::Waiting) else {
            return false;
        };
        // Role-owned control (docs/room-enums.md "Waiting master
        // gate"): master hits START, non-master hits READY. Seam:
        // `Self::is_room_master`.
        staged_rect_hit(
            &art.placements,
            waiting_confirm_control_id(self.is_room_master()),
            x,
            y,
        )
    }

    /// Waiting button click: staged START/READY runs the Confirm
    /// gate, staged BACK leaves for rooms. Art-less clicks land
    /// nowhere — no pinned fallback geometry names these buttons.
    fn click_waiting_button(&mut self, x: i32, y: i32) {
        let Some(art) = self.scene_art(Screen::Waiting) else {
            return;
        };
        let placements = &art.placements;
        // Team buttons first: the toggle-group map (`FUN_0048c810`,
        // `waiting_team_for_code`) lights the pressed team and queues
        // the 4004+4008 send pair through `select_team`.
        if let Some(team) = waiting_team_at(placements, x, y) {
            self.select_team(team);
            return;
        }
        // Song-select open trigger: the room master's MUSELECT button
        // (`IDC_BUTTON_SWAIT_MUSELECT`, file `0xb2622`) stages the
        // dialog. Non-master clicks are dropped by the exe, so they
        // stay a no-op here. Reopens after an OK close by restoring
        // the cached dialog art (ticket #266); a fresh stage is used
        // when nothing was cached yet.
        let mu_select = staged_rect_hit(placements, "IDC_BUTTON_SWAIT_MUSELECT", x, y);
        if mu_select && self.is_room_master() {
            self.select_music_notice = None;
            if self.select_music_art.is_none() {
                // A reopened dialog starts unfiltered, like the exe's
                // ctor sentinels (VAs `0x43d324`/`0x43d331`/`0x43d33e`).
                self.reset_select_chrome();
                if let Some(cached) = self.select_music_art_cache.clone() {
                    self.select_music_art = Some(cached);
                } else {
                    self.load_select_music_scene(Vec::new(), HashMap::new());
                }
            }
            return;
        }
        let back = WAITING_BACK_IDS
            .iter()
            .any(|id| staged_rect_hit(placements, id, x, y));
        // Role-owned control (docs/room-enums.md "Waiting master
        // gate"): master confirms on START, guests on READY.
        let confirm = staged_rect_hit(
            placements,
            waiting_confirm_control_id(self.is_room_master()),
            x,
            y,
        );
        if back {
            self.enter(Screen::Room);
        } else if confirm {
            self.confirm_waiting();
        }
    }

    /// Hit one result button: the staged `.bnd` rect verbatim where
    /// bound, the pinned `docs/cresult-anchors.md` rect otherwise.
    fn result_button_hit(&self, id: &str, fallback: &Rect, x: i32, y: i32) -> bool {
        match self.scene_art(Screen::Result) {
            Some(art) if art.placements.iter().any(|placed| placed.id == id) => {
                staged_rect_hit(&art.placements, id, x, y)
            }
            _ => rect_hit(fallback, x, y),
        }
    }

    /// Result button click: RETRY re-enters Waiting, BACK leaves
    /// for rooms — the keyboard Confirm/Back arms on mouse. Both
    /// presses queue their pinned relay body for the session bridge
    /// (4010 `0xfaa` / 4021 `0xfb5`, both empty).
    fn click_result_button(&mut self, x: i32, y: i32) {
        if self.result_button_hit(RESULT_RETRY_ID, &RESULT_RETRY_RECT, x, y) {
            self.outbox.pending_result_retry = true;
            self.enter(Screen::Waiting);
        } else if self.result_button_hit(RESULT_BACK_ID, &RESULT_BACK_RECT, x, y) {
            self.outbox.pending_result_back = true;
            self.enter(Screen::Room);
        }
    }

    /// Remember the host song choice (`SetRoomMusic` 4000 body);
    /// Waiting paints its title and difficulty panel, and the chosen
    /// chart's difficulty byte selects the playing life-bar deltas.
    /// Also resolves the album cover (see [`Self::resolve_song_cover`]).
    pub fn set_selected_music(&mut self, selection: SetRoomMusic) -> &mut Self {
        self.selected_music = Some(selection);
        self.apply_life_difficulty();
        self.resolve_song_cover();
        self
    }

    /// Stage a live loading status (real gate fractions only — see
    /// `recomp2jam::loading`; unknown stays `None`, never invented).
    /// The fraction is the gate phase ([`LOADING_GATE_PHASES`]):
    /// callers thread entry plus the staging/decrypt/decode/arm
    /// steps through `loading_phase_status` (or the armed full
    /// fraction straight from a completed chart stage), and reaching
    /// the armed fraction is the only way the gate phase reaches the
    /// arm — Confirm alone never advances it. A latched failure
    /// still holds the phase back.
    pub fn set_loading_status(&mut self, status: LoadingStatus) -> &mut Self {
        let phase = loading_phase_for_progress(status.progress);
        if !self.loading_gate_failed {
            self.loading_gate_phase = self.loading_gate_phase.max(phase);
        }
        self.loading_status = Some(status);
        self
    }

    /// Forget the walk state: Loading paints indeterminate again;
    /// the gate phase drops to entry and any latched failure clears,
    /// so the next song re-walks the gate from validation.
    pub fn clear_loading(&mut self) -> &mut Self {
        self.loading_status = None;
        self.loading_gate_phase = 0;
        self.loading_gate_failed = false;
        self
    }

    /// The pick the song-select staged (`None` until a music is
    /// picked): the loading gate validates it on the Loading edge.
    #[must_use]
    pub fn selected_music(&self) -> Option<SetRoomMusic> {
        self.selected_music
    }

    /// Whether an audio rig is attached (the gate requires one: the
    /// sample clock rides its backend).
    #[must_use]
    pub fn has_audio(&self) -> bool {
        self.audio.is_some()
    }

    /// Gate phase held by the walk (0 entry, 1 staging, 2 OJN
    /// decrypt, 3 Vorbis decode, 4 clock armed) — where the staged
    /// fractions currently stand. Stays at entry while nothing
    /// stages.
    #[must_use]
    pub fn loading_gate_phase(&self) -> usize {
        self.loading_gate_phase
    }

    /// Whether the gate has latched a failure (bad chart,
    /// undecryptable OJN, missing audio): the gate then holds
    /// Loading until a fresh [`Self::clear_loading`] re-walks it.
    #[must_use]
    pub fn loading_gate_failed(&self) -> bool {
        self.loading_gate_failed
    }

    /// Latch a loading failure (bad chart bytes, an OJN the decrypt
    /// rejects, a bank leg that decoded nothing): the gate holds
    /// Loading and never advances or arms on it, whatever fraction a
    /// later status stages. The caller clears it with
    /// [`Self::clear_loading`] when the song changes.
    pub fn fail_loading_gate(&mut self) {
        self.loading_gate_failed = true;
    }

    /// Select validation behind the Loading-to-Playing gate
    /// (lifecycle section 9, step 1: `0x5718b0`, ev `66e60d16...`):
    /// the picked song carries a nonzero id and a known difficulty
    /// slot (`Difficulty::from_code`; Rx maps to the Hard slice
    /// downstream, like the session's level map), and when the song
    /// table is staged the id must name one of its songs. No pick or
    /// no table match rejects before any file work matters.
    ///
    /// OPEN: with no catalog staged the table membership stays
    /// unverifiable (the offline/manual chart paths stage no table),
    /// so only the id/difficulty shape gates there — the table check
    /// engages once the catalog stages.
    #[must_use]
    pub fn validate_loading_select(&self) -> bool {
        let Some(selection) = self.selected_music.as_ref() else {
            return false;
        };
        if selection.music_id == 0 {
            return false;
        }
        if Difficulty::from_code(selection.difficulty).is_none() {
            return false;
        }
        if !self.catalog_songs.is_empty()
            && !self
                .catalog_songs
                .iter()
                .any(|song| song.song_id == u32::from(selection.music_id))
        {
            return false;
        }
        true
    }

    /// Whether the gate stands ready to arm the song clock and hand
    /// off to Playing: no latched failure, validation holds, the
    /// walk reached the armed phase (staging, OJN decrypt, and
    /// Vorbis init all staged before it), and an audio rig is
    /// attached — missing audio never arms, so the sample clock
    /// [`Self::now_ms`] always has a backend behind it. Confirm and
    /// the test driver hold in Loading while this is `false`; the
    /// scene stays honest.
    #[must_use]
    pub fn loading_gate_ready(&self) -> bool {
        !self.loading_gate_failed
            && self.loading_gate_phase >= LOADING_GATE_PHASES
            && self.validate_loading_select()
            && self.audio.is_some()
    }

    /// Live loading status, if a real gate walk staged one.
    #[must_use]
    pub fn loading_status(&self) -> Option<&LoadingStatus> {
        self.loading_status.as_ref()
    }

    /// Stage the walked chart's OJN cover into the loading scene under
    /// [`LOADING_COVER_SPRITE`]: the full-bleed song illustration the
    /// loading painter stretches first, replacing the genuine
    /// `MusicLoading.ojs` planet fallback (the exe mounts that overlay
    /// only when the song load returns 0, file `0xe47a0`). `true` while
    /// the bytes decode to a cover; any miss — non-chart bytes, unknown
    /// magic, undecodable stream — drops a previously staged cover, so
    /// the miss keeps the planet fallback. Archives stay read-only;
    /// nothing is invented.
    pub fn stage_loading_cover(&mut self, chart_bytes: &[u8]) -> bool {
        match ojn_cover_figure(chart_bytes) {
            Some(figure) => {
                self.scene_art[scene_index(Screen::Loading)]
                    .get_or_insert_with(SceneArt::default)
                    .figures
                    .insert(LOADING_COVER_SPRITE.to_owned(), figure);
                true
            }
            None => {
                self.clear_loading_cover();
                false
            }
        }
    }

    /// Whether the walked chart's OJN cover is staged for the loading
    /// gate (present means the chart load succeeded, so the painter
    /// skips the planet fallback).
    #[must_use]
    pub fn has_loading_cover(&self) -> bool {
        self.scene_art[scene_index(Screen::Loading)]
            .as_ref()
            .is_some_and(|art| art.figures.contains_key(LOADING_COVER_SPRITE))
    }

    /// Drop any staged loading cover so the next paint falls back to
    /// the planet overlay.
    fn clear_loading_cover(&mut self) {
        if let Some(art) = self.scene_art[scene_index(Screen::Loading)].as_mut() {
            art.figures.remove(LOADING_COVER_SPRITE);
        }
    }

    /// Seed the playing life bar from the selected chart's difficulty
    /// (Ex/Nx/Hx → Easy/Normal/Hard deltas per `FUN_00570f90`); codes
    /// without a verified arm (Rx, unknown) keep the current set. Runs
    /// on both setup points — chart load and song selection — so the
    /// flow order never matters.
    fn apply_life_difficulty(&mut self) {
        let Some(selection) = self.selected_music.as_ref() else {
            return;
        };
        self.playing.set_life_difficulty(selection.difficulty);
    }

    /// Stage the song catalog (`OJNList.dat` order, owned copies) for
    /// the select-music table, the waiting `MUSICNAME` caption, AND the
    /// lanking
    /// and music-shop boards (same parse, ticket #192: the live boot
    /// stages only this catalog, so the boards ride it instead of
    /// waiting for a separate staging call). Dead slots stay out; a missing catalog paints dialog art without rows.
    /// The BPM column stages alongside for the waiting `BPM` caption,
    /// and the container tokens for the album-cover path (see
    /// [`Self::resolve_song_cover`]). Label buckets stay unstaged, so
    /// the dialog's label filter keeps no row.
    pub fn set_song_catalog(&mut self, entries: &[OjnListEntry<'_>]) -> &mut Self {
        self.set_song_catalog_with_labels(entries, &[])
    }

    /// Stage the song catalog with its `OJNList.dat` table-5 label
    /// buckets (the song-dialog label column's input, ticket #273);
    /// every other board stages exactly as [`Self::set_song_catalog`]
    /// does.
    ///
    /// The songs also take the staged install scan's availability
    /// (`docs/music-availability.md` §1): catalog staging may run
    /// before or after [`Self::set_installed_music`], and the rows
    /// carry the scan's answer either way.
    pub fn set_song_catalog_with_labels(
        &mut self,
        entries: &[OjnListEntry<'_>],
        labels: &[OjnMidTagEntry],
    ) -> &mut Self {
        self.catalog_songs =
            select_music_songs_with_labels(entries, labels, self.installed_music.as_ref());
        self.catalog_bpm = entries
            .iter()
            .filter(|entry| entry.is_song())
            .map(|entry| (entry.song_id, entry.bpm))
            .collect();
        self.catalog_chart_files = entries
            .iter()
            .filter(|entry| entry.is_song())
            .map(|entry| (entry.song_id, entry.ojm_file.clone()))
            .collect();
        // The lanking and music-shop boards ride the same `OJNList.dat`
        // catalog as the select-music table: stage them here so the live
        // boot (which stages the song catalog through `stage_session_catalog`)
        // never leaves those boards empty without a separate staging call
        // (mirrors #191's avatar-source hook for the item shop).
        self.lanking.set_catalog(entries);
        self.music_shop.set_catalog(entries);
        self.resolve_song_cover();
        self
    }

    /// Stage the install's local music availability: the `Music`
    /// folder scan packed into the seat shape
    /// (`docs/music-availability.md` §1, [`o2jam_file::installed_music`]).
    ///
    /// The install decides which songs exist, never the server and
    /// never the catalog. A scan that never ran (`None`: the install
    /// carries no `Music` folder) keeps every catalog song selectable,
    /// the pre-#276 answer — no local knowledge, no invented notice.
    /// Catalog staging may run before or after this call: the staged
    /// songs take the new answer in place either way.
    pub fn set_installed_music(&mut self, installed: Option<InstalledMusic>) -> &mut Self {
        self.installed_music = installed;
        for song in &mut self.catalog_songs {
            song.set_installed(song_installed(song.song_id, self.installed_music.as_ref()));
        }
        self
    }

    /// Caption the select dialog shows instead of its status line
    /// (`None` while nothing was refused): the pinned not-downloaded
    /// notice a pick of an unavailable song raises (§3).
    #[must_use]
    pub fn select_music_notice(&self) -> Option<&'static str> {
        self.select_music_notice
    }

    /// Load the selected song's album cover from the staged catalog
    /// plus the install's `Music` folder. Runs on both staging points —
    /// catalog and song selection — so the flow order never matters.
    /// The selection's id names a catalog record, whose container token
    /// (`o2ma757.ojm`) swaps to the chart file (`o2ma757.ojn`; the
    /// shipped tokens match their chart files 14/14) and the OJN cover
    /// section ([`o2jam_file::ojn_cover_jpeg`],
    /// [`o2jam_file::decode_ojn_cover`], docs/file-formats/ojn.md)
    /// decodes to the box image. Any miss — no selection, no catalog
    /// record, no install, undecodable cover — leaves `None` and the
    /// staged music-name box paints as-is; nothing is invented.
    fn resolve_song_cover(&mut self) {
        self.song_cover = None;
        self.clear_loading_cover();
        let Some(selection) = self.selected_music.as_ref() else {
            return;
        };
        let Some(token) = self.catalog_chart_files.get(&u32::from(selection.music_id)) else {
            return;
        };
        let Some(path) = chart_cover_path(token) else {
            return;
        };
        let Ok(bytes) = std::fs::read(path) else {
            return;
        };
        let Ok(cover) = o2jam_file::ojn_cover_jpeg(&bytes) else {
            return;
        };
        let Ok(decoded) = o2jam_file::decode_ojn_cover(&cover) else {
            return;
        };
        self.song_cover = cover_image(&decoded);
        // The same walked bytes feed the loading scene: the cover the
        // gate walked is the illustration the loading painter stretches.
        self.stage_loading_cover(&bytes);
    }

    /// Stage real song-select dialog art (`DAILOG_SELECTMUSIC` placements
    /// plus figures loaded through `load_scene_figures`). Waiting layers
    /// it over the seats; empty art paints nothing extra.
    /// Stage select-music dialog art into the cache only, without
    /// opening the dialog overlay (ticket #270). The open state stays
    /// false from boot; MUSELECT restores the cached art to open.
    pub fn cache_select_music_scene(
        &mut self,
        placements: Vec<ScenePlacement>,
        figures: HashMap<String, AvatarFigure>,
    ) -> &mut Self {
        let art = SceneArt {
            placements,
            figures,
        };
        self.select_music_art_cache = Some(art);
        self
    }

    /// Stage real song-select dialog art (`DAILOG_SELECTMUSIC` placements
    /// plus figures) and open the dialog overlay. Used by MUSELECT
    /// reopen and tests. Opening clears the filter columns, the exe's
    /// ctor sentinels (VAs `0x43d324`/`0x43d331`/`0x43d33e`).
    pub fn load_select_music_scene(
        &mut self,
        placements: Vec<ScenePlacement>,
        figures: HashMap<String, AvatarFigure>,
    ) -> &mut Self {
        let art = SceneArt {
            placements,
            figures,
        };
        self.reset_select_chrome();
        self.select_music_art_cache = Some(art.clone());
        self.select_music_art = Some(art);
        self
    }

    /// Opening state of the song dialog's chrome: song panel, no help
    /// sheet, first page, empty search draft (exe ctor VAs
    /// `0x43d324`/`0x43d331`/`0x43d33e` plus the empty edit box).
    fn reset_select_chrome(&mut self) {
        self.select_filter = SelectMusicFilter::ALL;
        self.select_mode = SelectMusicMode::SongSelect;
        self.select_help = SelectHelpSheet::None;
        self.select_page = 0;
        self.select_search_field = SelectSearchField::Title;
        self.select_search_draft.clear();
        self.select_search_query = None;
    }

    /// Staged select-music catalog songs (catalog order, dead slots
    /// filtered out). Empty without catalog data.
    #[must_use]
    pub fn select_songs(&self) -> &[SelectMusicSong] {
        &self.catalog_songs
    }

    /// Played song's album cover, if it resolved from the walked
    /// chart's OJN cover section (see [`Self::resolve_song_cover`]).
    #[must_use]
    pub fn song_cover(&self) -> Option<&Rgb555Image> {
        self.song_cover.as_ref()
    }

    /// Catalog title for one song id, if staged.
    fn catalog_song_title(&self, music_id: u16) -> Option<&str> {
        let wanted = u32::from(music_id);
        self.catalog_songs
            .iter()
            .find(|song| song.song_id == wanted)
            .map(|song| song.title.as_str())
    }

    /// Song behind the `MUSICNAME` caption (rect 22, top bar): the
    /// master's staged pick when one stands — it takes effect at once,
    /// where the room mirror moves only on the server echo — else the
    /// joined room's song. The catalog supplies the title when it names
    /// the id (room-fill string flow, `docs/channel-fill.md`); without
    /// a title the caption paints the bare `M{id}` fallback.
    fn waiting_song(&self) -> Option<WaitingSong<'_>> {
        if let Some(pick) = self.selected_music {
            return Some(WaitingSong {
                music_id: pick.music_id,
                title: self.catalog_song_title(pick.music_id),
            });
        }
        let room = self.waiting.as_ref()?;
        Some(WaitingSong {
            music_id: room.music_id,
            title: self.catalog_song_title(room.music_id),
        })
    }

    /// Difficulty and speed behind the `LEVEL` badge (rect 26, left of
    /// the room title): the master's staged pick first, else the joined
    /// room's echo — the same source order as [`Self::waiting_song`],
    /// because the badge names the same song the caption does. A room
    /// that names no song paints no badge: the exe resets the control to
    /// no image (file `0x4ba88d`, setter arg 0).
    fn waiting_level(&self) -> Option<WaitingLevel> {
        if let Some(pick) = self.selected_music {
            return (pick.music_id != 0).then_some(WaitingLevel {
                difficulty: pick.difficulty,
                speed: pick.speed,
            });
        }
        let room = self.waiting.as_ref()?;
        (room.music_id != 0).then_some(WaitingLevel {
            difficulty: room.difficulty,
            speed: room.speed,
        })
    }

    /// Catalog BPM for one song id, if a live song record stages it.
    fn catalog_song_bpm(&self, music_id: u16) -> Option<f32> {
        self.catalog_bpm.get(&u32::from(music_id)).copied()
    }

    /// Catalog BPM for the song the `BPM` caption names: the staged
    /// pick first, else the room echo (`OJNList.dat` row +20 column).
    /// `None` paints the pinned `-0-` mismatch default.
    fn waiting_song_bpm(&self) -> Option<f32> {
        let song = self.waiting_song()?;
        self.catalog_song_bpm(song.music_id)
    }

    /// Stage the owned-item inventory counts, one per skill slot (the
    /// waiting `SKILLCOUNT` caption source; `JoinedRoom.skills`
    /// carries the ring ids only).
    pub fn set_skill_counts(&mut self, counts: [u32; 3]) -> &mut Self {
        self.skill_counts = counts;
        self
    }

    /// Staged inventory counts, one per skill slot (zeroed until
    /// staged).
    #[must_use]
    pub fn skill_counts(&self) -> [u32; 3] {
        self.skill_counts
    }

    /// Stage battle totals (`RoomTeams` mirrors the server-side 4014/4016
    /// accumulation); the result verdict reads rank 1 from these totals.
    pub fn set_battle_teams(&mut self, teams: RoomTeams) -> &mut Self {
        self.battle_teams = teams;
        self
    }

    /// Claim the local battle team (winner art compares this seat team
    /// against rank 1; `None` clears the claim and hides the verdict).
    pub fn set_battle_self_team(&mut self, team: Option<u8>) -> &mut Self {
        self.battle_self_team = team;
        self
    }

    /// Deliver scripted rank bytes through the peer mirror (shot-walk
    /// fixture only — same honesty as the duo nicknames): seeds the
    /// holder bytes, then broadcasts the packet through the verified
    /// rank-remap rule (`PeerBars::apply_rank_broadcast`). Returns the
    /// per-position deliveries. Zero convention unchanged: unmatched
    /// bytes leave their rows zeroed and hidden.
    pub fn stage_scripted_ranks(
        &mut self,
        global: u8,
        stored: [u8; PEER_SLOT_COUNT],
        packet: [u8; PEER_SLOT_COUNT],
    ) -> Vec<RankDelivery> {
        self.playing.set_rank_holders(global, stored);
        self.playing.apply_peer_ranks(packet)
    }

    /// Live play behind the highway: the session's tick source
    /// (Life/Jam channels read score, life, and bonus through it).
    #[must_use]
    pub fn live_play(&self) -> &LivePlay {
        &self.playing
    }

    /// Live life word for the session Life channel: the avatar
    /// gauge's bar value (row 0 of [`Self::result_rank_rows`]
    /// carries points, jam level, and bonus — never life).
    #[must_use]
    pub fn life(&self) -> u16 {
        self.playing.life()
    }

    /// Fold one live 4015 echo into the Playing peer mirror: the
    /// stats write first (seating its gauge), then the 8-byte rank
    /// broadcast (filling result rows under the remap rule) — the
    /// same order the session bridge applies, so the session mirror
    /// and the painted bars never diverge. Returns the queue forward
    /// plus the rank deliveries.
    pub fn apply_peer_echo(
        &mut self,
        slot: u8,
        kind: u16,
        value: u16,
        packet: [u8; PEER_SLOT_COUNT],
    ) -> (Option<QueueEvent>, Vec<RankDelivery>) {
        let queue = self.playing.apply_peer_stats(slot, kind, value);
        let ranks = self.playing.apply_peer_ranks(packet);
        (queue, ranks)
    }

    /// Rank-1 battle verdict for the claimed local team, if known.
    #[must_use]
    pub fn battle_verdict(&self) -> Option<BattleVerdict> {
        battle_verdict(&self.battle_teams, self.battle_self_team)
    }

    /// Result verdict for the banner: solo rooms (and no room at
    /// all) take the solo banner; team battles carry the rank-1
    /// verdict when it resolves (`FUN_004c3120` branches).
    #[must_use]
    pub fn result_verdict(&self) -> ResultVerdict {
        if self.room_team_play() {
            ResultVerdict::Battle(self.battle_verdict())
        } else {
            ResultVerdict::Solo
        }
    }

    /// Saturated local points for the rank row's `%8d` field (the
    /// exe's 32-bit read; the u64 accumulator saturates — PERF-07:
    /// `TryFrom`, never `as`).
    fn saturate_rank_score(points: u64) -> u32 {
        u32::try_from(points).unwrap_or(u32::MAX)
    }

    /// Rank number for display row `position`: the `PeerBars` byte
    /// there, hidden solo (the exe draws `%d` at x=91 only with 2+
    /// players) and skipped while zero (empty seats ride zero bytes
    /// — the `live_rank_rows` convention in `side.rs`). Zero means
    /// no broadcast delivered a rank there yet: the song path never
    /// seeds stored ranks, so only a real 4015 broadcast with
    /// matching members fills this in.
    fn result_row_rank(peers: &PeerBars, position: usize, row_count: usize) -> Option<u8> {
        if row_count < 2 {
            return None;
        }
        let rank = peers.rank_row(position)?;
        (rank != 0).then_some(rank)
    }

    /// Live result rank rows: joined-room member names in seat order
    /// (self `YOU` first — local-only, the wire sends no self
    /// nickname — then the occupied wire slots, capped at eight), and
    /// each seat's digits from the admitted 4018 member record when
    /// one stands. The local `Score`/`LongNoteBonus` falls back only
    /// where no record names that seat: offline play stages no 4018,
    /// and the exe's local +0x31 writer stays unpinned. Rank bytes
    /// still ride `PeerBars`; speed comes from the record's `+0x2168`
    /// or the shared room code when no record stands.
    #[must_use]
    pub fn result_rank_rows(&self) -> Vec<ResultRankRow> {
        let score = self.playing.score();
        let bonus_points = self.playing.bonus().points();
        let peers = self.playing.peers();
        let room = self.waiting.as_ref();
        let speed = room.map(|joined| joined.speed);
        // (name, +0x31 portrait byte, 4018 member seat)
        let mut names: Vec<(String, Option<u8>, Option<u8>)> =
            vec![("YOU".to_owned(), None, room.map(|joined| joined.member_id))];
        if let Some(joined) = room {
            for slot in joined.slots.iter().take(7) {
                if let Some(member) = slot.member.as_ref() {
                    // The member record +0x31 the row painter reads
                    // is the first 4043 MemberInfo seat byte; the
                    // shell stages no 4043 table, so the joined
                    // room's team byte rides in its place, raw. The
                    // waiting-room team rides 0–7 while the 4043
                    // byte is consumed 1-based (byte 0 = team-bucket
                    // skip): whether the result copy already holds
                    // 1-based bytes stays OPEN (next step: populated
                    // battle-row capture, docs/cresult-anchors.md).
                    names.push((member.nickname.clone(), Some(member.team), Some(slot.index)));
                }
            }
        }
        let row_count = names.len().min(8);
        names
            .into_iter()
            .take(8)
            .enumerate()
            .map(|(position, (name, seat_byte, member_id))| {
                let local = position == 0;
                let record = member_id
                    .and_then(|id| self.result_member_records.get(usize::from(id)))
                    .copied()
                    .flatten();
                ResultRankRow {
                    rank: Self::result_row_rank(peers, position, row_count),
                    name: Some(name),
                    judgements: record
                        .map(|row| {
                            [
                                u32::from(row.cool),
                                u32::from(row.good),
                                u32::from(row.bad),
                                u32::from(row.miss),
                            ]
                        })
                        .or_else(|| local.then_some(score.counts)),
                    combos: record
                        .map(|row| (u32::from(row.max_combo), u32::from(row.jam_combo)))
                        .or_else(|| local.then_some((score.max_combo, score.jam.level()))),
                    score: record
                        .map(|row| row.score)
                        .or_else(|| local.then_some(Self::saturate_rank_score(score.points))),
                    // `+0x2164` is the reward cell, not the long-note
                    // word at `+0x2158` (unpainted — OPEN).
                    bonus: record
                        .map(|row| u64::from(row.reward))
                        .or_else(|| local.then_some(bonus_points)),
                    speed: record.map(|row| row.speed).or(speed),
                    // The local row's +0x31 writer is unpinned (the
                    // shell stages no local member record): row 0
                    // resolves no chip until a source lands — the
                    // exe attaches a constant slot per row, so this
                    // only gates the unpinned local byte, never a
                    // worn figure (OPEN, docs/cresult-anchors.md).
                    seat_byte,
                }
            })
            .collect()
    }

    /// Grade plate frame for the finished play, if a chart loaded.
    /// The ratio runs the live scorer total against the pinned
    /// `grade_max_reference` denominator for the chart's note word
    /// (docs/cresult-anchors.md) through the pinned table
    /// [`result_grade_frame`]. The word counts chart onsets; the
    /// exe's 26 unscored records are a documented gap.
    #[must_use]
    pub fn grade(&self) -> Option<u8> {
        let word = u16::try_from(self.chart_notes).unwrap_or(u16::MAX);
        super::paint::result_grade_frame(self.playing.score(), word)
    }

    /// Stage real main-flow art for one screen: `.bnd` placements
    /// (via `bind_scene_rects`, or full-canvas for unbound blocks)
    /// plus figures loaded through `load_scene_figures`. Paint
    /// layers the live UI over it; empty art keeps the flat fallback.
    pub fn load_scene(
        &mut self,
        screen: Screen,
        placements: Vec<ScenePlacement>,
        figures: HashMap<String, AvatarFigure>,
    ) -> &mut Self {
        self.scene_art[scene_index(screen)] = Some(SceneArt {
            placements,
            figures,
        });
        self
    }

    /// Merge extra figures into one screen's staged art — a sprite
    /// the exe mounts from another archive, like `PointNum.ojs` on
    /// the Result scene (`this+0x10d10`, Playing archive;
    /// `docs/cresult-anchors.md`). Inserts into the staged map and
    /// stages empty art when the screen holds none; placements stay
    /// untouched. Figures whose names already stage are overwritten.
    pub fn merge_scene_figures(
        &mut self,
        screen: Screen,
        figures: HashMap<String, AvatarFigure>,
    ) -> &mut Self {
        let art = self.scene_art[scene_index(screen)].get_or_insert_with(SceneArt::default);
        art.figures.extend(figures);
        self
    }

    /// Stage one Messenger sheet's parsed rects in a hidden slot:
    /// the live boot parks them here so geometry stays data-driven,
    /// but no sheet paints or owns input until an exe mount pin
    /// exists (spec #315 story 12; ADR-0012).
    pub fn load_messenger_sheet(&mut self, sheet: MessengerSheet, art: SceneArt) -> &mut Self {
        self.messenger_art.insert(sheet, art);
        self
    }

    /// Staged rects for one Messenger sheet, for geometry guards.
    #[must_use]
    pub fn messenger_sheet_placements(&self, sheet: MessengerSheet) -> &[ScenePlacement] {
        self.messenger_art
            .get(&sheet)
            .map_or(&[], |art| art.placements.as_slice())
    }

    /// True while one Messenger sheet's rects are staged. The live
    /// boot gate asserts all six park before any sheet can open.
    #[must_use]
    pub fn messenger_sheet_staged(&self, sheet: MessengerSheet) -> bool {
        self.messenger_art.contains_key(&sheet)
    }

    /// Park one cart-add sheet's parsed rects: the live boot stages the
    /// geometry, but no painter consumes it until an exe mount pin exists
    /// (`SHOPPINGBAG_ADD_NEXT_STEP`, spec #316 story 11).
    pub fn load_shopping_bag_add_sheet(&mut self, art: SceneArt) -> &mut Self {
        self.shopping_bag_add_art = Some(art);
        self
    }

    /// True while the cart-add sheet's rects are staged. Geometry only:
    /// no mount, no wire, and no input ownership (ADR-0012).
    #[must_use]
    pub fn shopping_bag_add_art_staged(&self) -> bool {
        self.shopping_bag_add_art.is_some()
    }

    /// Staged placements for one screen, if any (read-only accessor
    /// for live-path guards; empty when the screen holds no staged
    /// art).
    #[must_use]
    pub fn scene_placements(&self, screen: Screen) -> &[ScenePlacement] {
        self.scene_art[scene_index(screen)]
            .as_ref()
            .map_or(&[], |art| &art.placements)
    }

    /// Staged art for one screen, if any.
    fn scene_art(&self, screen: Screen) -> Option<&SceneArt> {
        self.scene_art[scene_index(screen)].as_ref()
    }

    /// Open side screen, if any.
    #[must_use]
    pub fn side(&self) -> Option<SideScreen> {
        self.side
    }

    /// Chart globals written by the pinned Room FIRSTSTEP entry
    /// (`S-PLAY-B3`), `None` until that control answers.
    #[must_use]
    pub const fn tutorial_chart_globals(&self) -> Option<TutorialChartGlobals> {
        self.tutorial_chart_globals
    }

    /// Stage real side art: `.bnd` placements plus figures loaded
    /// through [`load_scene_figures`](super::super::avatar::load_scene_figures).
    pub fn load_side_scene(
        &mut self,
        placements: Vec<ScenePlacement>,
        figures: HashMap<String, AvatarFigure>,
    ) -> &mut Self {
        self.side_placements = placements;
        self.side_figures = figures;
        self
    }

    /// Planet board click through the control-code → action
    /// dispatch table ([`planet_action_at`]): lit-emblem presses
    /// record the family pick and open the channel dialog through
    /// the flow gate (`Planet`→`Channel`, the dialog-over-board
    /// phase flag `parent+0xF64` in the exe); power opens the
    /// quit-confirm modal, gear the options modal, promotion cells
    /// record the press and drive the carousel (LEFT/RIGHT step
    /// with wrap, STOP toggles rotation — exe-pinned,
    /// `docs/planet.md`).
    /// The emblems are server channel families (live-verified 2026-11-09,
    /// `docs/planet.md` "Live verification"). FREE/DRUM stay
    /// unbound (P0).
    ///
    /// OPEN links (never invented): the exe emblem handler ends at
    /// family-select + reconnect (E1,
    /// `docs/overnight-evidence/e1-channel-dialog-trigger.md`) —
    /// the emblem → dialog-visibility edge is dynamic-only, with
    /// the named next step a stopped-state winedbg memory watch on
    /// the dialog flag during an emblem click. The same-family
    /// blank-rows effect (re-selecting the active family reconnects
    /// without re-fetching, live-verified) rides the session's
    /// channel refetch, not this shell flag. Launcher preselection
    /// (the boot auto-open observation) stays OPEN: the shell boots
    /// the bare board and the dialog opens only here, never at boot.
    /// The amber-cursor stand-in stays labeled OPEN.
    pub fn click_planet(&mut self, x: i32, y: i32) {
        // The whole-gesture driver walks the pinned split: the press
        // arms on down, the action dispatches on release-inside up.
        self.planet_pointer_down(x, y);
        self.planet_pointer_up(x, y);
    }

    fn click_dispatch(&mut self, x: i32, y: i32) {
        if self.messenger_liveness_open {
            // The one-OK sheet owns every click until OK; it sends
            // no wire (Memoryer has no messenger endpoint).
            if self.information_ok_hit(x, y) {
                self.messenger_liveness_open = false;
            }
            return;
        }
        if self.room_no_response_dialog_open() {
            if self.information_ok_hit(x, y) {
                self.post_room_no_response_dismissal();
            }
            return;
        }
        if self.click_side_screen(x, y) {
            return;
        }
        if self.planet_modal().is_some() {
            self.click_planet_modal(x, y);
            return;
        }
        if self.flow.current() == Screen::Room && self.room_dialog.is_some() {
            self.click_room_dialog(x, y);
            return;
        }
        match self.flow.current() {
            // #385: no exe pin makes a canvas click an Avi dismiss
            // edge; the click stand-in is removed. Only the armed
            // byte codes (ESC/CR, `avi_key`) leave the splash.
            Screen::Avi => {}
            Screen::Channel => self.click_channel_row(x, y),
            Screen::Room => self.click_room_row(x, y),
            Screen::Waiting => self.click_waiting(x, y),
            Screen::Result => self.click_result_button(x, y),
            // Planet board click: hit-test at the pinned `.bnd`
            // button rects and record the difficulty pick. What a
            // pick DOES on confirm is evidence-OPEN (docs/planet.md
            // OPEN 6: solo entry), and the FREE/DRUM back ends were
            // never wired (P0), so every outcome stays a no-op.
            Screen::Planet => {
                self.click_planet(x, y);
            }
            // Ranking clicks on the flow screen land nowhere: the
            // live board answers through the side-screen path
            // (`click_lanking` over staged `side_placements`).
            Screen::Lanking => {}
            // Avatar-room flow clicks land nowhere: the flow screen
            // is not side-entered (the transition map has no lobby
            // edge into it) — the side overlay owns the dispatch
            // (`click_myroom_side`).
            Screen::Myroom => {}
            // Shop clicks land nowhere: buy, gift, cart, filter, and
            // pager semantics are all unevidenced (P0).
            Screen::Shop | Screen::MusicShop => {}
            Screen::Loading | Screen::Playing => {}
        }
    }

    /// Tutorial exit hit test: use the staged `Playing_Exit.ojs` rect
    /// when the art is present, otherwise the same anchor from the
    /// archive pin. The qualified boot1 press `(777,567)` lands here.
    fn tutorial_exit_hit(&self, x: i32, y: i32) -> bool {
        let rect = self
            .side_placements
            .iter()
            .find(|placed| placed.sprite.as_deref() == Some(TUTORIAL_EXIT_SPRITE))
            .map_or(TUTORIAL_EXIT_HIT_RECT, |placed| placed.rect);
        let offset_x = i64::from(x) - i64::from(rect.x);
        let offset_y = i64::from(y) - i64::from(rect.y);
        offset_x >= 0
            && offset_x < i64::from(rect.w)
            && offset_y >= 0
            && offset_y < i64::from(rect.h)
    }

    /// The open side screen answers its named controls at staged
    /// rects (lanking: sorts, pagers, row picks; shop: row toggles,
    /// buys, pagers, sorts; my room: the side overlay; tutorial: the
    /// bottom-right exit); every other side screen stays click-silent.
    /// Returns whether the click was consumed.
    fn click_side_screen(&mut self, x: i32, y: i32) -> bool {
        if self.side == Some(SideScreen::Tutorial) {
            if self.tutorial_exit_hit(x, y) {
                let _ = self.leave_side();
            }
            return true;
        }
        if self.side == Some(SideScreen::Lanking) {
            self.click_lanking(x, y);
            return true;
        }
        if self.side == Some(SideScreen::Shop) {
            self.click_shop(x, y);
            return true;
        }
        if self.side == Some(SideScreen::Payment) {
            self.click_cash_charge_close(x, y);
            return true;
        }
        if self.side == Some(SideScreen::MusicShop) {
            self.click_music_shop(x, y);
            return true;
        }
        if self.side.is_some() {
            if self.side == Some(SideScreen::MyRoom) {
                self.click_myroom_side(x, y);
            }
            return true;
        }
        false
    }

    /// One press on the staged close sprite dismisses the billing
    /// sheet and returns to the shop that opened it (boot 3). Other
    /// billing clicks stay consumed; the web bridge is unwired.
    fn click_cash_charge_close(&mut self, x: i32, y: i32) {
        let close_pressed = self
            .cash_charge_art
            .as_ref()
            .is_some_and(|art| cash_charge_close_hit(&art.dialog, x, y));
        if close_pressed {
            let _ = self.leave_side();
        }
    }

    /// Waiting clicks: the song-select dialog consumes first, the
    /// staged room buttons answer only what it passes over.
    fn click_waiting(&mut self, x: i32, y: i32) {
        if !self.click_select_music(x, y) {
            self.click_waiting_button(x, y);
        }
    }

    /// The planet board with no side screen and no modal owns it —
    /// the only scene with a pinned press/release split (#111).
    fn bare_planet_board(&self) -> bool {
        self.side.is_none()
            && self.planet_modal().is_none()
            && self.flow.current() == Screen::Planet
    }

    /// The room lobby with no side sheet, no room dialog, and no
    /// options modal owns it — the only room state where the worn
    /// figure slot is fully visible (the planet bare-board mirror).
    fn bare_room_board(&self) -> bool {
        self.side.is_none() && self.room_dialog.is_none() && self.planet_modal().is_none()
    }

    /// Worn figure behind the Room user-panel slot, if staged and
    /// non-empty (an empty figure stages no pulse, the waiting-seat
    /// rule).
    fn room_worn_figure_shown(&self) -> bool {
        self.room_avatar
            .as_ref()
            .is_some_and(|figure| !figure.is_empty())
    }

    /// Any worn figure behind the Waiting seats: a staged seat figure
    /// arms the pulse, else the lobby `room_avatar` covers seat 0
    /// until the fetched seat lands (the painter's dual-source
    /// fallback).
    fn waiting_worn_figure_shown(&self) -> bool {
        self.waiting_figures
            .iter()
            .any(|slot| slot.as_ref().is_some_and(|figure| !figure.is_empty()))
            || self.room_worn_figure_shown()
    }

    /// Apply one press edge at native frame pixels: the shared
    /// helper behind the snapshot press edge — a press lands where
    /// the pointer is, so hover
    /// and press agree even when no motion preceded the press.
    fn apply_pointer_down(&mut self, x: i32, y: i32) {
        self.pointer = Some((x, y));
        if self.bare_planet_board() {
            // Pinned press feedback (#111): the planet board arms the
            // press on down and fires the action on release-inside.
            self.planet_pointer_down(x, y);
            return;
        }
        // Channel scrollbar drag arm (#174): press on the bar body
        // (track between the two arrows) sets the drag capture;
        // arrows still click-step via click_dispatch.
        if self.flow.current() == Screen::Channel && self.channel_scene.arm_drag(x, y) {
            return;
        }
        // Every other scene keeps its down-dispatch (no press-split
        // evidence there; the room-scene quickjoin arm is the named
        // next capture, `docs/hover.md`).
        self.click_dispatch(x, y);
    }

    /// Apply one release edge at native frame pixels: the shared
    /// helper behind the snapshot release edge (release-inside
    /// fires, pinned #111 arm 3).
    fn apply_pointer_up(&mut self, x: i32, y: i32) {
        self.pointer = Some((x, y));
        if self.bare_planet_board() {
            self.planet_pointer_up(x, y);
        }
        if self.flow.current() == Screen::Channel {
            self.channel_scene.end_drag();
        }
    }

    /// Arm the board press on left-down over the bare board (pinned
    /// #111 arm 1: the pressed frame swaps on ButtonDown, per control
    /// — only when the staged art carries a pressed frame). Elsewhere
    /// — and while a modal owns the board — the press lands nowhere
    /// (the same gate the click router uses).
    fn planet_pointer_down(&mut self, x: i32, y: i32) {
        if self.flow.current() != Screen::Planet || self.planet_modal().is_some() {
            return;
        }
        let placements: &[ScenePlacement] = self
            .scene_art(Screen::Planet)
            .map_or(&[], |art| &art.placements);
        let press = planet_action_at(placements, x, y);
        self.planet_board.arm_press(press);
    }

    /// Release the board press (left-up). Release-inside reverts and
    /// fires the action on up (pinned #111 arm 3); release-outside
    /// reverts to REST with no action (arm 4 — the revert trigger,
    /// rect-exit vs up, stays OPEN, `docs/hover.md`; this stand-in
    /// reverts on up).
    fn planet_pointer_up(&mut self, x: i32, y: i32) {
        let Some(pressed) = self.planet_board.take_press() else {
            return;
        };
        if self.flow.current() != Screen::Planet || self.planet_modal().is_some() {
            return;
        }
        let placements: &[ScenePlacement] = self
            .scene_art(Screen::Planet)
            .map_or(&[], |art| &art.placements);
        if planet_action_at(placements, x, y) == Some(pressed) {
            self.dispatch_planet_action(pressed);
        }
    }

    /// Run one board action (the release-inside click, pinned on up
    /// not down, #111 arm 3). The board state owns the arms; the
    /// flow step rides the reported family pick.
    fn dispatch_planet_action(&mut self, action: PlanetAction) {
        // The disc and emblem handlers cue before they open the modal
        // or step the scene (VA `0x48e087` exit, `0x48e316` emblem).
        if matches!(action, PlanetAction::QuitConfirm) {
            self.cue_ui_effect(UiEffectId::PlanetExit);
        }
        if self
            .planet_board
            .apply_action(action, self.promo_frame_count())
        {
            self.cue_ui_effect(UiEffectId::EmblemPick);
            self.enter(Screen::Channel);
        }
    }

