    /// Modal click: the quit popup's OK/CANCEL (staged dialog
    /// rects when art is staged, the fallback boxes otherwise) or
    /// the options dialog's staged buttons (EXIT closes without
    /// saving, SAVE commits to `option.ini`, DEFAULT restores the
    /// tab's exe defaults, tab switches flip the sheet, and the
    /// Key/Sound/Game buttons edit the settings — staged rects
    /// only, Escape closes the unstaged dialog). Other clicks land
    /// nowhere: the modal owns the board while open.
    fn click_planet_modal(&mut self, x: i32, y: i32) {
        match self.planet_board.planet_modal {
            Some(PlanetModal::QuitConfirm) => {
                let (ok_hit, cancel_hit) = self.quit_button_hits(x, y);
                if ok_hit {
                    self.cue_ui_effect(UiEffectId::DialogAccept);
                    self.quit_requested = true;
                    self.planet_board.close_modal();
                } else if cancel_hit {
                    self.cue_ui_effect(UiEffectId::DialogDecline);
                    self.planet_board.close_modal();
                }
            }
            Some(PlanetModal::Options) => {
                self.click_options_dialog(x, y);
            }
            Some(PlanetModal::RelayDown) if self.relay_ok_hit(x, y) => {
                self.dismiss_relay_down_dialog();
            }
            Some(PlanetModal::RelayDown) => {}
            Some(PlanetModal::ChannelEnterRefused) if self.information_ok_hit(x, y) => {
                self.dismiss_channel_refusal_dialog();
            }
            Some(PlanetModal::ChannelEnterRefused) => {}
            None => {}
        }
    }

    /// One click inside the open options tab: the dialog changes its
    /// own settings and reports whether EXIT closed it, so the game
    /// keeps ownership of the modal.
    fn click_options_dialog(&mut self, x: i32, y: i32) {
        let volume_before = self.options_dialog.settings().bgm_music();
        let outcome = self.options_dialog.click(x, y);
        if outcome.close {
            self.planet_board.close_modal();
        }
        if let Some(effect) = outcome.effect {
            self.cue_ui_effect(effect);
        }
        // The dialog sits over the lobby: a BGMusic slider move must
        // re-cue the running scene track at its new gain without a
        // scene change. Other edits keep their existing paths.
        if self.options_dialog.settings().bgm_music() != volume_before {
            self.apply_scene_bgm();
        }
    }

    /// Quit-popup OK/CANCEL hits: staged dialog rects when art is
    /// staged ([`dialog_rect_hit`]), the native fallback boxes
    /// otherwise ([`quit_fallback_rects`]).
    fn quit_button_hits(&self, x: i32, y: i32) -> (bool, bool) {
        let staged = self
            .planet_quit_art
            .as_ref()
            .filter(|art| art.has_figures());
        if let Some(art) = staged {
            (
                dialog_rect_hit(&art.placements, QUIT_OK_CODE, x, y),
                dialog_rect_hit(&art.placements, QUIT_CANCEL_CODE, x, y),
            )
        } else {
            let (_, ok, cancel) = quit_fallback_rects();
            (rect_hit(&ok, x, y), rect_hit(&cancel, x, y))
        }
    }

    /// One-OK Information sheet hit for `0X21200002`: its staged
    /// `.bnd` rect when art is staged, else the archive-less fallback
    /// plate. Shared by the relay notice and the Room fuse (#367).
    fn information_ok_hit(&self, x: i32, y: i32) -> bool {
        let staged = self.relay_down_art.as_ref().filter(|art| art.has_figures());
        if let Some(art) = staged {
            dialog_rect_hit(&art.placements, INFORMATION_OK_CODE, x, y)
        } else {
            rect_hit(&information_ok_fallback_rect(), x, y)
        }
    }

    /// Relay notice OK hit on the same Information sheet.
    fn relay_ok_hit(&self, x: i32, y: i32) -> bool {
        self.information_ok_hit(x, y)
    }

