    #[test]
    fn staged_catalog_and_selection_load_the_walked_cover() {
        // End to end on a real install: the 757 token maps to
        // `Music/o2ma757.ojn`, whose OJN cover section decodes to the
        // 800x600 album art (docs/file-formats/ojn.md). Skips when
        // `install-root` is absent.
        let chart = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../install-root/O2Jam/Music/o2ma757.ojn");
        let Ok(_) = std::fs::read(&chart) else {
            return;
        };
        let mut game = ScreenGame::new();
        stage_waiting_song(&mut game);
        let cover = game.song_cover().expect("the walked cover resolves");
        assert_eq!((cover.w, cover.h), (800, 600));
    }

    #[test]
    fn result_paint_layers_the_cover_over_the_scene_ink() {
        // The full loop: the result scene paints, the cover fills the
        // box interior at its pinned rect (dest (0,0) samples the
        // cover's own (0,0)), driven by the staged catalog + selection.
        // Skips when `install-root` is absent.
        let chart = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../install-root/O2Jam/Music/o2ma757.ojn");
        let Ok(bytes) = std::fs::read(&chart) else {
            return;
        };
        let cover_bytes = o2jam_file::ojn_cover_jpeg(&bytes).unwrap();
        let cover = cover_image(&o2jam_file::decode_ojn_cover(&cover_bytes).unwrap());
        let mut game = ScreenGame::new();
        stage_waiting_song(&mut game);
        game.load_chart(vec![(2, 5000, 7)]);
        walk_to_playing(&mut game);
        game.strike_at(2, 5000);
        let mut buf = vec![0u32; 800 * 600];
        game.paint_at(
            &mut Frame {
                buf: &mut buf,
                w: 800,
                h: 600,
            },
            7_000,
        );
        assert_eq!(game.screen(), Screen::Result);
        let at =
            |x: i32, y: i32| buf[usize::try_from(y).unwrap() * 800 + usize::try_from(x).unwrap()];
        // The box interior's top-left pixel carries the cover's
        // top-left ink, widened to the frame (the wiring target).
        let word = cover.as_ref().expect("cover resolves").words[0];
        let (r, g, b) = (
            (((word >> 10) & 31) as u8) << 3 | (((word >> 10) & 31) as u8) >> 2,
            (((word >> 5) & 31) as u8) << 3 | (((word >> 5) & 31) as u8) >> 2,
            ((word & 31) as u8) << 3 | ((word & 31) as u8) >> 2,
        );
        assert_eq!(
            at(RESULT_MUSIC_BOX.x, RESULT_MUSIC_BOX.y),
            pack_xrgb(r, g, b)
        );
    }

    fn paint_waiting_frame(game: &mut ScreenGame, w: usize, h: usize) -> Vec<u32> {
        let mut buf = vec![0u32; w * h];
        game.paint_at(
            &mut Frame {
                buf: &mut buf,
                w,
                h,
            },
            0,
        );
        buf
    }

    /// Native rect of the staged `MUSICNAME` TEXT control: the `.bnd`
    /// pairing the scene carried in, never a literal (pinned
    /// `State_Waiting.bnd` rect 22, 7.55).
    fn staged_musicname_rect(game: &ScreenGame) -> Rect {
        game.scene_art(Screen::Waiting)
            .and_then(|art| {
                art.placements
                    .iter()
                    .find(|placed| placed.id == "IDC_TEXT_SWAIT_MUSICNAME")
            })
            .map(|placed| placed.rect)
            .expect("staged MUSICNAME placement")
    }

    /// Waiting game on the staged caption scene: the joined room names
    /// `room_music_id`, the catalog names song 757, and an optional
    /// staged pick names `pick`.
    fn musicname_pick_game(room_music_id: u16, pick: Option<u16>) -> ScreenGame {
        let mut game = ScreenGame::new();
        let mut room = waiting_room();
        room.music_id = room_music_id;
        game.set_joined_room(room);
        walk_to_waiting(&mut game);
        let blob = waiting_song_catalog_blob();
        let entries = o2jam_file::parse_ojn_list(&blob).unwrap();
        game.set_song_catalog(&entries);
        if let Some(music_id) = pick {
            game.set_selected_music(o2jam_net::play::SetRoomMusic {
                music_id,
                difficulty: 2,
                speed: 3,
            });
        }
        let (placements, figures) = musicname_scene();
        game.load_scene(Screen::Waiting, placements, figures);
        game
    }

    #[test]
    fn staged_pick_titles_the_bound_musicname_caption() {
        // Live chain: main.rs::run_play -> Shell::run ->
        //   ScreenGame::paint -> ScreenGame::paint_at -> paint_waiting ->
        //   paint_waiting_scene -> paint_waiting_staged ->
        //   paint_waiting_music
        // `MUSICNAME` is the `State_Waiting.bnd` TEXT control
        // (`IDC_TEXT_SWAIT_MUSICNAME`, code `0X16400017`, rect 22). The
        // master's staged pick names it at once, so a room that names
        // the picked song and a room that names nothing plus the pick
        // ink the same caption.
        let mut picked = musicname_pick_game(0, Some(757));
        let mut room_named = musicname_pick_game(757, None);
        let rect = staged_musicname_rect(&picked);
        let picked_frame = paint_waiting_frame(&mut picked, 800, 600);
        let named_frame = paint_waiting_frame(&mut room_named, 800, 600);
        assert!(
            ink_near(
                &picked_frame,
                800,
                600,
                (rect.x, rect.y),
                (
                    i32::try_from(rect.w).unwrap_or(0),
                    i32::try_from(rect.h).unwrap_or(0)
                ),
                pack_xrgb(0xFF, 0xFF, 0xFF)
            ),
            "the staged pick inks no caption inside the MUSICNAME rect"
        );
        assert!(
            o2jam_render::pixels_in_rect(&picked_frame, 800, rect)
                == o2jam_render::pixels_in_rect(&named_frame, 800, rect),
            "the caption must carry the staged pick's title, not the room's"
        );
    }

    #[test]
    fn staged_pick_leaves_the_musicname_plate_without_a_scrim() {
        // Live chain: main.rs::run_play -> Shell::run ->
        //   ScreenGame::paint -> ScreenGame::paint_at -> paint_waiting ->
        //   paint_waiting_scene -> paint_waiting_staged ->
        //   paint_waiting_music
        // Ticket #274: the chosen title must ink the `.bnd` plate
        // alone. The old caption scrim filled the four pixels just
        // outside its top-left corner; those pixels stay clear.
        let mut picked = musicname_pick_game(0, Some(757));
        let rect = staged_musicname_rect(&picked);
        let frame = paint_waiting_frame(&mut picked, 800, 600);
        let corner = (
            usize::try_from(rect.x - 4).unwrap_or(0),
            usize::try_from(rect.y - 2).unwrap_or(0),
        );
        assert_ne!(
            frame[corner.1 * 800 + corner.0],
            pack_xrgb(0x08, 0x08, 0x10),
            "the pinned plate must not carry a shell scrim"
        );
    }

    /// Bottom edge of the lowest staged seat cover: the seat grid's
    /// lower bound. The chat box sits under it, and the #274 readout
    /// panel used to ink exactly that band (`(w/8, h*3/4)`).
    fn seat_grid_bottom(placements: &[ScenePlacement]) -> u32 {
        placements
            .iter()
            .filter(|placed| placed.id.starts_with("IDC_IMAGE_SWAIT_COVERAVATAR"))
            .map(|placed| u32::try_from(placed.rect.y).unwrap_or(0) + placed.rect.h)
            .max()
            .unwrap_or(0)
    }

    #[test]
    fn staged_pick_inks_nothing_below_the_seat_grid() {
        // Live chain: main.rs::run_play -> Shell::run ->
        //   ScreenGame::paint -> ScreenGame::paint_at -> paint_waiting ->
        //   paint_waiting_scene -> paint_waiting_staged
        // Ticket #274: the chosen-song readout used to paint a dark
        // panel plus rows above the chat area. Staging a pick may now
        // ink the top-bar caption and nothing under the seat grid.
        let mut bare = musicname_pick_game(0, None);
        let mut picked = musicname_pick_game(0, Some(757));
        let grid_bottom = seat_grid_bottom(picked.scene_placements(Screen::Waiting));
        assert!(grid_bottom > 0, "the staged scene carries seat covers");
        let seat_grid = Rect {
            x: 0,
            y: 0,
            w: 800,
            h: grid_bottom,
        };
        let bare_frame = paint_waiting_frame(&mut bare, 800, 600);
        let picked_frame = paint_waiting_frame(&mut picked, 800, 600);
        let changed =
            o2jam_render::first_change_outside(&bare_frame, &picked_frame, 800, seat_grid);
        assert!(
            changed.is_none(),
            "the pick must not ink the chat band: first pixel changed below the seat grid: {changed:?}"
        );
    }

    /// Cell count of the synthetic `Wait_Level.ojs` body: the three
    /// standard difficulty families at their 12 speed cells.
    const LEVEL_BADGE_CELLS: u8 = 36;

    /// RGB555 body pixel of one synthetic badge cell: full red plus the
    /// cell's own code in green, so the painted frame names itself and
    /// no cell collapses onto the transparent key.
    fn level_badge_cell_word(cell: u8) -> u16 {
        0x7C00 | (u16::from(cell) << 5)
    }

    /// Framebuffer word [`level_badge_cell_word`] blits as.
    fn level_badge_cell_ink(cell: u8) -> u32 {
        let (r, g, b) = o2jam_render::expand_rgb555(level_badge_cell_word(cell));
        pack_xrgb(r, g, b)
    }

    /// Staged waiting covers plus the `LEVEL` badge rect (rects 60 and
    /// 26): the difficulty/speed badge stage. Every synthetic cell is a
    /// 1x1 layer at anchor `(0,0)` (the real body's anchors, so the
    /// bound rect positions it) whose colour names the cell, so the
    /// frame that wins reads straight from the buffer.
    fn level_badge_scene() -> (Vec<ScenePlacement>, HashMap<String, AvatarFigure>) {
        let mut body = AvatarFigure::default();
        for cell in 0..LEVEL_BADGE_CELLS {
            body.push_layer(FigureLayer {
                image: Rgb555Image::decode(&level_badge_cell_word(cell).to_le_bytes(), 1, 1)
                    .unwrap(),
                dx: 0,
                dy: 0,
                colorkey: 0xFFFF,
            });
        }
        (
            vec![
                ScenePlacement {
                    role: PlacementRole::Single,
                    id: "IDC_IMAGE_SWAIT_COVERAVATAR1".to_owned(),
                    code: 0,
                    sprite: None,
                    rect: Rect {
                        x: 28,
                        y: 53,
                        w: 141,
                        h: 175,
                    },
                },
                ScenePlacement {
                    role: PlacementRole::Single,
                    id: "IDC_IMAGE_SWAIT_LEVEL".to_owned(),
                    code: 0,
                    sprite: Some("Wait_Level.ojs".to_owned()),
                    rect: Rect {
                        x: 218,
                        y: 12,
                        w: 55,
                        h: 28,
                    },
                },
            ],
            HashMap::from([("Wait_Level.ojs".to_owned(), body)]),
        )
    }

    /// Waiting game on the badge stage: the joined room names
    /// `room_music_id` (difficulty 1, speed 2), with an optional staged
    /// pick.
    fn level_badge_game(room_music_id: u16, pick: Option<SetRoomMusic>) -> ScreenGame {
        let mut game = ScreenGame::new();
        let mut room = waiting_room();
        room.music_id = room_music_id;
        room.difficulty = 1;
        room.speed = 2;
        game.set_joined_room(room);
        walk_to_waiting(&mut game);
        if let Some(pick) = pick {
            game.set_selected_music(pick);
        }
        let (placements, figures) = level_badge_scene();
        game.load_scene(Screen::Waiting, placements, figures);
        game
    }

    /// Inked pixels inside the staged badge rect, in rect order.
    fn level_badge_ink(game: &ScreenGame, frame: &[u32]) -> Vec<u32> {
        let badge = game
            .scene_placements(Screen::Waiting)
            .iter()
            .find(|placed| placed.id == "IDC_IMAGE_SWAIT_LEVEL")
            .map(|placed| placed.rect)
            .expect("staged LEVEL placement");
        o2jam_render::pixels_in_rect(frame, 800, badge)
            .into_iter()
            .filter(|pixel| *pixel != 0)
            .collect()
    }

    #[test]
    fn staged_pick_badge_paints_the_level_frame_the_pick_names() {
        // Live chain: main.rs::run_play -> Shell::run ->
        //   ScreenGame::paint -> ScreenGame::paint_at -> paint_waiting ->
        //   paint_waiting_scene -> paint_waiting_staged ->
        //   paint_waiting_level_badge
        // Ticket #275: the `LEVEL` badge (`IDC_IMAGE_SWAIT_LEVEL`,
        // code `0X1650001B`, `State_Waiting.bnd` rect 26, left of the
        // room title) carries the picked difficulty plus the speed
        // cell. The exe stages `12*difficulty + speed + 1` (setter VA
        // `0x42f870` subtracts the one), so a hard/speed-3 pick paints
        // layer `12*2 + 3 = 27` alone - one frame, never the 36-cell
        // stack the exe's image control replaced.
        let mut game = level_badge_game(
            0,
            Some(SetRoomMusic {
                music_id: 757,
                difficulty: 2,
                speed: 3,
            }),
        );
        let frame = paint_waiting_frame(&mut game, 800, 600);
        assert_eq!(
            level_badge_ink(&game, &frame),
            vec![level_badge_cell_ink(27)],
            "the badge must paint the pick's single frame (HX at speed 3)"
        );
    }

    #[test]
    fn room_without_a_song_paints_no_level_badge() {
        // Live chain: main.rs::run_play -> Shell::run ->
        //   ScreenGame::paint -> ScreenGame::paint_at -> paint_waiting ->
        //   paint_waiting_scene -> paint_waiting_staged ->
        //   paint_waiting_level_badge
        // The exe resets the badge control when no song stands (file
        // `0x4ba88d`, setter arg 0 paints no image), so a room with no
        // song leaves the badge rect untouched - the rest stack may not
        // ink its staged frames there either.
        let mut game = level_badge_game(0, None);
        let frame = paint_waiting_frame(&mut game, 800, 600);
        assert_eq!(
            level_badge_ink(&game, &frame),
            Vec::<u32>::new(),
            "a room with no song paints no badge"
        );
    }

