    fn region_has_ink(buf: &[u32], frame_w: usize, x: i32, y: i32, w: i32, h: i32) -> bool {
        buf.chunks(frame_w)
            .skip(y as usize)
            .take(h as usize)
            .any(|row| {
                row.iter()
                    .skip(x as usize)
                    .take(w as usize)
                    .any(|pixel| *pixel != 0)
            })
    }

