    #[test]
    fn options_tab_switches_open_each_own_staged_sheet() {
        // Live chain: main.rs::run_online -> run_windowed_session ->
        // window::InputHandler::route_mouse_edge -> GameLoop::ingest_snapshot
        // -> ScreenGame::apply_pointer_down -> click_dispatch -> click_planet
        // -> click_planet_modal -> click_options_dialog -> OptionsDialog::click
        // -> PlanetOptionTab::switch_tab. The six switch codes belong to
        // their own sheets: a code pressed on a foreign sheet answers
        // nothing (its rect is not staged there).
        use super::super::side::{
            OPTION_GAME_KEYSET, OPTION_GAME_SOUNDSET, OPTION_KEY_GAMESET, OPTION_KEY_SOUNDSET,
            OPTION_SOUND_GAMESET, OPTION_SOUND_KEYSET,
        };
        let cases = [
            (
                PlanetOptionTab::Key,
                OPTION_KEY_SOUNDSET,
                PlanetOptionTab::Sound,
            ),
            (
                PlanetOptionTab::Key,
                OPTION_KEY_GAMESET,
                PlanetOptionTab::Game,
            ),
            (
                PlanetOptionTab::Sound,
                OPTION_SOUND_KEYSET,
                PlanetOptionTab::Key,
            ),
            (
                PlanetOptionTab::Sound,
                OPTION_SOUND_GAMESET,
                PlanetOptionTab::Game,
            ),
            (
                PlanetOptionTab::Game,
                OPTION_GAME_KEYSET,
                PlanetOptionTab::Key,
            ),
            (
                PlanetOptionTab::Game,
                OPTION_GAME_SOUNDSET,
                PlanetOptionTab::Sound,
            ),
        ];
        for (owner, code, expected) in cases {
            let mut game = ScreenGame::new();
            stage_option_buttons(&mut game, owner, &[(code, 100, 100)]);
            open_options(&mut game);
            game.switch_option_tab(owner);
            click_button(&mut game, 100, 100);
            assert_eq!(
                game.planet_option_tab(),
                expected,
                "{owner:?} {code:#010X} must open its own sheet"
            );
        }
    }

    #[test]
    fn options_save_commits_beside_the_install_root() {
        let root = std::env::temp_dir().join(format!("recomp2jam-options-{}", std::process::id()));
        std::fs::create_dir_all(&root).unwrap();
        let mut game = ScreenGame::new();
        game.load_options(&root);
        stage_option_buttons(
            &mut game,
            PlanetOptionTab::Key,
            &[(OPTION_KEY_LANE_FIRST, 100, 100)],
        );
        stage_option_buttons(
            &mut game,
            PlanetOptionTab::Sound,
            &[(PlanetOptionTab::Sound.save_code(), 100, 100)],
        );
        open_options(&mut game);
        game.switch_option_tab(PlanetOptionTab::Key);
        click_button(&mut game, 100, 100);
        assert!(game.capture_raw_key(winit::keyboard::KeyCode::KeyA, true));
        game.switch_option_tab(PlanetOptionTab::Sound);
        click_button(&mut game, 100, 100);
        let text = std::fs::read_to_string(root.join("option.ini")).unwrap();
        assert!(
            text.contains("KEY_1=30"),
            "rebound A persists as its DirectInput code: {text}"
        );
        let reloaded = crate::options::OptionsSettings::load_from_dir(&root);
        assert_eq!(reloaded, *game.options(), "a restart keeps them");
        std::fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn options_exit_closes_without_saving() {
        let root =
            std::env::temp_dir().join(format!("recomp2jam-options-exit-{}", std::process::id()));
        std::fs::create_dir_all(&root).unwrap();
        let mut game = ScreenGame::new();
        game.load_options(&root);
        let exit = PlanetOptionTab::Key.exit_code();
        stage_option_buttons(
            &mut game,
            PlanetOptionTab::Key,
            &[(OPTION_GAME_NOTETYPE2, 100, 100), (exit, 200, 100)],
        );
        open_options(&mut game);
        game.switch_option_tab(PlanetOptionTab::Game);
        // The Game sheet is unstaged: no button answers, and the
        // Key-tab EXIT rect belongs to the other sheet.
        click_button(&mut game, 200, 100);
        assert_eq!(
            game.planet_modal(),
            Some(PlanetModal::Options),
            "unstaged tabs answer nothing"
        );
        game.switch_option_tab(PlanetOptionTab::Key);
        click_button(&mut game, 200, 100);
        assert_eq!(game.planet_modal(), None, "EXIT closes");
        assert!(
            !root.join("option.ini").exists(),
            "EXIT abandons: only SAVE commits"
        );
        std::fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn options_default_restores_the_exe_defaults_per_tab() {
        let mut game = ScreenGame::new();
        let default = PlanetOptionTab::Key.default_code();
        stage_option_buttons(
            &mut game,
            PlanetOptionTab::Game,
            &[
                (OPTION_GAME_NOTETYPE2, 100, 100),
                (OPTION_GAME_GUIDE_LONG, 140, 100),
                (default, 180, 100),
            ],
        );
        open_options(&mut game);
        game.switch_option_tab(PlanetOptionTab::Game);
        click_button(&mut game, 100, 100);
        click_button(&mut game, 140, 100);
        assert_eq!(game.options().note_type(), 1);
        // DEFAULT belongs to the Key tab sheet here, so the Game
        // values stand; staging it on the open tab restores them.
        click_button(&mut game, 180, 100);
        assert_eq!(game.options().note_type(), 1);
        stage_option_buttons(
            &mut game,
            PlanetOptionTab::Game,
            &[(PlanetOptionTab::Game.default_code(), 180, 100)],
        );
        click_button(&mut game, 180, 100);
        assert_eq!(game.options().note_type(), 0);
        assert_eq!(game.options().note_tail(), 2);
    }

    #[test]
    fn game_tab_default_restores_the_pinned_longnote_raw_default() {
        // Live chain: main.rs::run_online -> run_windowed_session ->
        // window::InputHandler::route_mouse_edge -> GameLoop::ingest_snapshot
        // -> ScreenGame::click_dispatch -> click_planet -> click_planet_modal
        // -> click_options_dialog -> OptionsDialog::click ->
        // OptionsSettings::reset_game. The exe reads raw
        // `LONGNOTEMODE` 3 (file `0x16fb06`) and its load path rewrites
        // it to 1 (`0x43a630`); DEFAULT must restore the effective 1.
        use super::super::side::OPTION_GAME_LONGNOTE_USED;
        use crate::options::DEFAULT_LONGNOTE_MODE;
        let mut game = ScreenGame::new();
        stage_option_buttons(
            &mut game,
            PlanetOptionTab::Game,
            &[
                (OPTION_GAME_LONGNOTE_USED, 100, 100),
                (PlanetOptionTab::Game.default_code(), 140, 100),
            ],
        );
        open_options(&mut game);
        game.switch_option_tab(PlanetOptionTab::Game);
        click_button(&mut game, 100, 100);
        assert!(game.options().longnote_used());
        click_button(&mut game, 140, 100);
        assert_eq!(
            game.options().longnote_mode(),
            DEFAULT_LONGNOTE_MODE,
            "Game DEFAULT restores the exe effective default, not 0"
        );
    }

    #[test]
    fn longnote_mode_snapshots_at_playing_entry() {
        let mut game = ScreenGame::new();
        assert_eq!(game.play_longnote_mode(), None);
        game.options_mut().set_longnote_mode(1);
        walk_to_playing(&mut game);
        assert_eq!(game.play_longnote_mode(), Some(1));
        game.options_mut().set_longnote_mode(0);
        assert_eq!(
            game.play_longnote_mode(),
            Some(1),
            "later dialog edits never reach the running song"
        );
    }

    #[test]
    fn key_strikes_play_at_the_game_effect_gain() {
        use o2jam_audio::{AudioBackend, AudioError, PcmSamples};
        use std::cell::RefCell;
        use std::rc::Rc;
        struct GainProbe {
            gains: Rc<RefCell<Vec<f32>>>,
        }
        impl AudioBackend for GainProbe {
            fn play_pcm(&mut self, _pcm: &PcmSamples) -> Result<(), AudioError> {
                Ok(())
            }
            fn play_key(&mut self, _pcm: &PcmSamples, gain: f32) -> Result<(), AudioError> {
                self.gains.borrow_mut().push(gain);
                Ok(())
            }
            fn samples_played(&self) -> u64 {
                0
            }
        }
        let gains = Rc::new(RefCell::new(Vec::new()));
        let probe = GainProbe {
            gains: Rc::clone(&gains),
        };
        let bank = HashMap::from([(
            7u32,
            PcmSamples {
                samples: vec![1000i16; 8],
                sample_rate: 8000,
                channels: 1,
            },
        )]);
        let mut game = ScreenGame::new();
        game.with_audio(Box::new(probe), bank);
        // Live chain: main.rs::run_online -> run_windowed_session ->
        // window::InputHandler::route_key -> GameLoop::lane_key ->
        // ScreenGame::strike_at -> pump_sounds ->
        // AudioBackend::play_key. The Sound tab edits the same GameEffect
        // value the strike mixer reads, so a stepped slider changes the
        // next strike gain without a scene change.
        game.load_chart(vec![(2, 5000, 7), (2, 6000, 7), (2, 7000, 7)]);
        for next in [
            Screen::Planet,
            Screen::Channel,
            Screen::Room,
            Screen::Waiting,
            Screen::Loading,
            Screen::Playing,
        ] {
            game.flow.go(next).unwrap();
        }
        game.strike_at(2, 5000);
        assert_eq!(gains.borrow().len(), 1);
        assert!((gains.borrow()[0] - 1.0).abs() < 1e-6);
        game.options_mut().step_game_effect(false);
        let stepped_gain = f32::from(255 - crate::options::SOUND_SLIDER_STEP) / 255.0;
        game.strike_at(2, 6000);
        assert_eq!(gains.borrow().len(), 2);
        assert!(
            (gains.borrow()[1] - stepped_gain).abs() < 1e-6,
            "one slider step scales the next strike: {:?}",
            gains.borrow()
        );
        for _ in 0..64 {
            game.options_mut().step_game_effect(false);
        }
        game.strike_at(2, 7000);
        assert_eq!(gains.borrow().len(), 3);
        assert!(gains.borrow()[2].abs() < 1e-6, "muted effect stays silent");
    }

    #[test]
    fn scene_bgm_cue_scales_with_the_bgmusic_volume() {
        use o2jam_audio::{AudioBackend, AudioError, PcmSamples};
        use std::cell::RefCell;
        use std::rc::Rc;
        struct PeakProbe {
            peaks: Rc<RefCell<Vec<i32>>>,
        }
        impl AudioBackend for PeakProbe {
            fn play_pcm(&mut self, _pcm: &PcmSamples) -> Result<(), AudioError> {
                Ok(())
            }
            fn set_scene_bgm(
                &mut self,
                pcm: Option<&PcmSamples>,
                _repeat: bool,
            ) -> Result<(), AudioError> {
                let peak = pcm.map_or(0, |pcm| {
                    pcm.samples
                        .iter()
                        .map(|s| i32::from(*s).abs())
                        .max()
                        .unwrap_or(0)
                });
                self.peaks.borrow_mut().push(peak);
                Ok(())
            }
            fn samples_played(&self) -> u64 {
                0
            }
        }
        let peaks = Rc::new(RefCell::new(Vec::new()));
        let probe = PeakProbe {
            peaks: Rc::clone(&peaks),
        };
        let mut bank = vec![None; 10];
        bank[8] = Some(PcmSamples {
            samples: vec![1000i16; 441],
            sample_rate: 44100,
            channels: 1,
        });
        let mut game = ScreenGame::new();
        game.with_audio(Box::new(probe), HashMap::new());
        game.stage_scene_bgm(bank);
        game.enter(Screen::Planet);
        assert_eq!(peaks.borrow().last(), Some(&1000));
        game.options_mut().step_bgm_music(false);
        game.enter(Screen::Channel);
        // One exe step: 1000 * 251 / 255 = 984.3, rounds to 984.
        assert_eq!(peaks.borrow().last(), Some(&984));
    }

    #[test]
    fn bgmusic_slider_re_cues_the_lobby_track_without_a_scene_change() {
        // Live chain: main.rs::run_online -> run_windowed_session ->
        // window::InputHandler::route_mouse_edge -> GameLoop::ingest_snapshot
        // -> ScreenGame::click_dispatch -> click_planet -> click_planet_modal
        // -> click_options_dialog -> apply_scene_bgm ->
        // AudioBackend::set_scene_bgm. The slider is a dialog over the
        // lobby, so the sounding cue must change on the click itself.
        use super::super::side::OPTION_SOUND_BG_MUSIC_DOWN;
        use o2jam_audio::{AudioBackend, AudioError, PcmSamples};
        use std::cell::RefCell;
        use std::rc::Rc;
        struct PeakProbe {
            peaks: Rc<RefCell<Vec<i32>>>,
        }
        impl AudioBackend for PeakProbe {
            fn play_pcm(&mut self, _pcm: &PcmSamples) -> Result<(), AudioError> {
                Ok(())
            }
            fn set_scene_bgm(
                &mut self,
                pcm: Option<&PcmSamples>,
                _repeat: bool,
            ) -> Result<(), AudioError> {
                let peak = pcm.map_or(0, |pcm| {
                    pcm.samples
                        .iter()
                        .map(|sample| i32::from(*sample).abs())
                        .max()
                        .unwrap_or(0)
                });
                self.peaks.borrow_mut().push(peak);
                Ok(())
            }
            fn samples_played(&self) -> u64 {
                0
            }
        }
        let peaks = Rc::new(RefCell::new(Vec::new()));
        let probe = PeakProbe {
            peaks: Rc::clone(&peaks),
        };
        let mut bank = vec![None; 10];
        // `SceneBgm::resolve` indexes record id minus one: slot 8 is
        // record 9, the Planet loop.
        bank[8] = Some(PcmSamples {
            samples: vec![1000i16; 441],
            sample_rate: 44100,
            channels: 1,
        });
        let mut game = ScreenGame::new();
        game.with_audio(Box::new(probe), HashMap::new());
        game.stage_scene_bgm(bank);
        game.enter(Screen::Planet);
        assert_eq!(peaks.borrow().last(), Some(&1000));
        stage_option_buttons(
            &mut game,
            PlanetOptionTab::Sound,
            &[(OPTION_SOUND_BG_MUSIC_DOWN, 100, 100)],
        );
        open_options(&mut game);
        game.switch_option_tab(PlanetOptionTab::Sound);
        click_button(&mut game, 100, 100);
        // One exe step: 1000 * 251 / 255 rounds to 984; no scene entry.
        assert_eq!(
            peaks.borrow().last(),
            Some(&984),
            "the slider re-cues the running lobby track"
        );
        assert_eq!(
            game.options().bgm_music(),
            255 - crate::options::SOUND_SLIDER_STEP
        );
    }

