    #[test]
    fn music_shop_prices_diff_and_wallet_reach_the_painted_side_board() {
        // Live caller chain:
        //   main.rs::stage_session_catalog ->
        //   OnlineSession::set_song_catalog_with_params ->
        //   ScreenGame::stage_music_shop_prices -> MusicShopState::stage_prices
        //   -> visit_side(MusicShop) -> ScreenGame::paint_side ->
        //   paint_music_shop_board / paint_music_shop_wallet.
        // Seam sufficiency: the real boot parses OJNList.dat table 3;
        // this guard supplies the same staged param row and checks the
        // painter, so no archive or gateway is needed.
        let mut game = ScreenGame::new();
        walk_to_waiting(&mut game);
        let blob = lanking_record(757, 124.0, "First", "Band");
        let entries = o2jam_file::parse_ojn_list(&blob).unwrap();
        game.set_song_catalog(&entries);
        game.stage_music_shop_prices(&[o2jam_file::OjnMidParamEntry {
            song_id: 757,
            param_a: 0,
            param_b: 3000,
            anchor: o2jam_file::OJN_MID_TABLE3_ANCHOR,
        }]);
        game.wallet = WalletState {
            gem: Some(15527),
            cash_point: Some(0),
            ..WalletState::default()
        };
        game.load_side_scene(music_shop_side_placements(), HashMap::new());
        assert!(game.visit_side(SideScreen::MusicShop));
        let mut buf = vec![0u32; 800 * 600];
        game.paint_side(
            &mut Frame {
                buf: &mut buf,
                w: 800,
                h: 600,
            },
            0,
        );
        let lit = |x: i32, y: i32, w: u32, h: u32| -> bool {
            (y..y + h as i32)
                .any(|row| (x..x + w as i32).any(|col| buf[row as usize * 800 + col as usize] != 0))
        };
        assert!(lit(315, 142, 50, 11), "DIFF cell inks from the catalog");
        assert!(lit(282, 158, 41, 11), "GEM cell inks from table 3");
        assert!(lit(282, 174, 41, 11), "WON cell inks from table 3");
        assert!(lit(41, 567, 95, 13), "bottom G wallet cell inks");
        assert!(lit(166, 567, 95, 13), "bottom W wallet cell inks");
    }

