    #[test]
    fn waiting_master_start_needs_every_peer_ready() {
        // `START 0x16202012` runs the all-ready check (file
        // `0xb5560`): an unready occupied peer blocks the master,
        // and the start fires once every peer is ready.
        let mut game = ScreenGame::new();
        let mut room = waiting_room();
        room.slots[0].index = 1;
        room.slots[0]
            .member
            .as_mut()
            .expect("fixture seats a peer")
            .ready = false;
        game.set_joined_room(room);
        walk_to_waiting(&mut game);
        assert!(game.is_room_master());
        assert!(!game.all_peers_ready());
        assert!(!game.can_start_game());
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Waiting);
        game.waiting.as_mut().expect("room joined").slots[0]
            .member
            .as_mut()
            .expect("fixture seats a peer")
            .ready = true;
        assert!(game.can_start_game());
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Loading);
    }

    /// The joined master's room plus one ready peer on the other team
    /// (the server hands every join the first unused team).
    fn waiting_room_with_peer(peer: RoomMember) -> JoinedRoom {
        let mut room = waiting_room();
        room.music_id = 757;
        room.slots.push(RoomSlot {
            index: 1,
            state_code: 1,
            member: Some(peer),
        });
        room.user_count = 2;
        room
    }

    /// A peer on team A (the self team is 1 in [`waiting_room`]).
    fn ready_peer() -> RoomMember {
        let mut peer = waiting_room().slots[0]
            .member
            .clone()
            .expect("fixture seats the master");
        peer.nickname = "peer".to_owned();
        peer.master = false;
        peer.team = 0;
        peer
    }

    #[test]
    fn start_gate_asks_for_the_music_when_a_peer_lacks_the_room_song() {
        // docs/music-availability.md §4a: an occupied peer seat whose
        // music state is NoMusic turns the gate into its -2 arm
        // (VA `0x4b5560`), and the click answers with 4034
        // AcquireMusicRequest (`0xfc2`) instead of 4010 — no notice,
        // the download starts on the 4035 answer.
        let mut game = ScreenGame::new();
        let mut peer = ready_peer();
        peer.music_state = o2jam_net::MusicState::NoMusic.code();
        game.set_joined_room(waiting_room_with_peer(peer));
        walk_to_waiting(&mut game);
        assert!(game.can_start_game());
        assert_eq!(game.start_gate_verdict(), StartGateVerdict::MusicMissing);
        assert_eq!(game.press_start(), StartRequest::AcquireMusic);
        assert_eq!(game.waiting_notice(), None);
    }

    #[test]
    fn start_gate_tests_readiness_before_the_team_and_music_arms() {
        // The exe tests in order: every peer ready (-1), then the team
        // histogram (-5), then each peer's music state (-2/-3/-4).
        let mut game = ScreenGame::new();
        let mut peer = ready_peer();
        peer.ready = false;
        peer.music_state = o2jam_net::MusicState::NoMusic.code();
        game.set_joined_room(waiting_room_with_peer(peer));
        walk_to_waiting(&mut game);
        assert_eq!(game.start_gate_verdict(), StartGateVerdict::PeerNotReady);
        assert_eq!(game.press_start(), StartRequest::Nothing);
        assert_eq!(game.waiting_notice(), Some(WAITING_START_NOT_READY_NOTICE));
    }

    #[test]
    fn start_gate_reads_the_team_shape_like_the_exe() {
        // Multiplayer rooms need at least two teams of equal size (the
        // exe's histogram arm; Memoryer's `TeamUnbalanced` test). One
        // team for everyone is the shape the server never sends, so the
        // gate reports it instead of starting.
        let mut game = ScreenGame::new();
        let mut peer = ready_peer();
        peer.team = 1; // the self team: one team only
        game.set_joined_room(waiting_room_with_peer(peer));
        walk_to_waiting(&mut game);
        assert_eq!(game.start_gate_verdict(), StartGateVerdict::TeamsUnbalanced);
        assert_eq!(game.press_start(), StartRequest::Nothing);
        assert_eq!(game.waiting_notice(), Some(WAITING_START_TEAMS_NOTICE));
        // Two teams of one player each pass, and the gate reaches its
        // music arm.
        game.set_joined_room(waiting_room_with_peer(ready_peer()));
        assert_eq!(game.start_gate_verdict(), StartGateVerdict::Startable);
        assert_eq!(game.press_start(), StartRequest::StartGame);
        assert_eq!(game.waiting_notice(), None);
    }

    #[test]
    fn start_click_during_a_download_only_rearms_the_face() {
        // §4a: the click handler's first arm — `scene+0x504 != 0` (a
        // transfer stands) re-arms the button face and sends nothing;
        // the player gets the download notice.
        let mut game = ScreenGame::new();
        game.set_joined_room(waiting_room_with_peer(ready_peer()));
        walk_to_waiting(&mut game);
        assert!(game.begin_music_download(757));
        assert!(game.music_download().is_running());
        assert_eq!(game.press_start(), StartRequest::Nothing);
        assert_eq!(game.waiting_notice(), Some(WAITING_START_DOWNLOAD_NOTICE));
        assert!(game.waiting_confirm_armed());
        // The queue holds the room song once, whatever the click count.
        game.press_start();
        assert_eq!(game.music_download().requests().len(), 1);
    }

    #[test]
    fn a_missing_room_song_announces_no_music_state() {
        // §2: the announcement is computed for the room's staged song;
        // with none (id 0) the client answers Ready rather than
        // inventing a NoMusic for a song nobody picked.
        let mut game = ScreenGame::new();
        game.set_joined_room(waiting_room());
        assert_eq!(game.room_music_id(), None);
        game.set_room_music(757, 2, 5);
        assert_eq!(game.room_music_id(), Some(757));
        // No install scan, no local knowledge: the pre-#276 answer.
        assert_eq!(game.music_state_for(757), o2jam_net::MusicState::Ready);
    }
    /// One room chrome control staged on its own test rect, on the
    /// walked Avi → Channel → Room path.
    fn room_lobby_with_control(code: u32, id: &str) -> ScreenGame {
        room_lobby_with_controls(&[(code, id)])
    }

    /// Room lobby with the given staged room placements.
    fn room_lobby_with_placements(placements: Vec<(u32, &str, Rect)>) -> ScreenGame {
        use MenuKey;
        let mut game = ScreenGame::new();
        game.set_channels(two_channels());
        game.set_rooms(two_rooms());
        game.menu_key(MenuKey::Back, true);
        game.click_planet(136, 88);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);
        let placements = placements
            .into_iter()
            .map(|(code, id, rect)| ScenePlacement {
                role: PlacementRole::Single,
                id: id.to_owned(),
                code,
                sprite: None,
                rect,
            })
            .collect();
        game.load_scene(Screen::Room, placements, HashMap::new());
        game
    }

    /// Room lobby with every given control staged on the shared test
    /// rect: the point is the code dispatch, so the fixture claims no
    /// geometry.
    fn room_lobby_with_controls(controls: &[(u32, &str)]) -> ScreenGame {
        room_lobby_with_placements(
            controls
                .iter()
                .map(|(code, id)| (*code, *id, ROOM_CONTROL_TEST_RECT))
                .collect(),
        )
    }

    /// Test rect for one staged chrome control: clear of the room row
    /// bands and of every other staged control.
    const ROOM_CONTROL_TEST_RECT: Rect = Rect {
        x: 400,
        y: 380,
        w: 40,
        h: 20,
    };
    /// Click point inside [`ROOM_CONTROL_TEST_RECT`].
    const ROOM_CONTROL_TEST_CLICK: (i32, i32) = (410, 385);

    #[test]
    fn room_enter_with_an_open_dialog_stays_in_the_lobby() {
        // The open room sheet owns the keyboard: Enter must neither
        // send the lobby draft nor leave for Waiting, and the draft
        // survives for when the sheet closes.
        let mut game = ScreenGame::new();
        // Boot → Planet → Channel → Room (the documented walk).
        game.menu_key(MenuKey::Back, true);
        game.click_planet(136, 88);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);
        game.open_create_room_dialog();
        game.set_lobby_input(LobbyChat::Room, "hello");
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room, "dialog keeps the lobby");
        assert_eq!(
            game.lobby_chat(LobbyChat::Room).draft(),
            "hello",
            "the draft is untouched"
        );
        // Entering the lobby again drops the sheet (the flow's own
        // room-entry reset); with an empty draft Enter leaves for
        // Waiting as before.
        game.menu_key(MenuKey::Back, true);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);
        game.set_lobby_input(LobbyChat::Room, "");
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Waiting);
    }

    #[test]
    fn staged_room_chrome_buttons_reach_their_side_views() {
        // Ticket #32: every VISIBLE room chrome button with a target
        // already in the tree answers on its staged rect and stays a
        // lobby visit. `MYBAND` (`0x1320003A`) is no longer in this
        // loop: ticket #169 pins it exe-hidden (the room-setup path
        // clears its draw-path words; sole binary references are the
        // three clears, file `0x8ee00`/`0x8ee27`/`0x8ee4e`), so no
        // staged rect — synthetic or bnd — answers in 7.55. Its route
        // stays in `ROOM_CONTROLS` as documentation, held out of
        // dispatch by `room_chrome_visible`; the hidden behavior is
        // guarded by `bundled_room_chrome_answers_no_click_or_hover`
        // and `bundled_room_chrome_paints_no_pixels`.
        for (code, id, side) in [
            (0x1320_0008, "IDC_BUTTON_SROOM_ITEMSHOP", SideScreen::Shop),
            (0x1320_0009, "IDC_BUTTON_SROOM_MYROOM", SideScreen::MyRoom),
            (
                0x1320_0037,
                "IDC_BUTTON_SROOM_MUSICSHOP",
                SideScreen::MusicShop,
            ),
        ] {
            let mut game = room_lobby_with_control(code, id);
            game.ingest_snapshot(&InputSnapshot::click_at(
                ROOM_CONTROL_TEST_CLICK.0,
                ROOM_CONTROL_TEST_CLICK.1,
            ));
            assert_eq!(game.side(), Some(side), "{id}");
            assert_eq!(game.screen(), Screen::Room, "{id}");
            assert_eq!(game.room_control_noop(), None, "{id}");
        }
        // Ticket #169: the bundled top-band chrome is exe-hidden, so
        // even when staged on the test rect it must not reach a side
        // view and must not be recorded as a labelled press.
        for (code, id) in [
            (0x1320_0038, "IDC_BUTTON_SROOM_MYCAPSULE"),
            (0x1320_0039, "IDC_BUTTON_SROOM_EVENT"),
            (0x1320_003A, "IDC_BUTTON_SROOM_MYBAND"),
        ] {
            let mut game = room_lobby_with_control(code, id);
            game.ingest_snapshot(&InputSnapshot::click_at(
                ROOM_CONTROL_TEST_CLICK.0,
                ROOM_CONTROL_TEST_CLICK.1,
            ));
            assert_eq!(game.side(), None, "{id}");
            assert_eq!(game.screen(), Screen::Room, "{id}");
            assert_eq!(game.room_control_noop(), None, "{id}");
        }
    }

    #[test]
    fn staged_firststep_button_enters_the_tutorial_flow() {
        // Ticket #34: the room top-right `FIRSTSTEP` chrome
        // (`0x13200032`, `Room_FirstStep.ojs`, hover rect 660,1-718,32
        // per `docs/hover.md`) visits the tutorial side state
        // (`CStateTutorial`) through the pinned `S-PLAY-B3` helper;
        // the lobby holds underneath and BACK returns to it. The
        // chart globals are pinned by
        // `firststep_click_from_boot_staged_room_sets_the_pinned_tutorial_globals`;
        // only the dead Planet plate stays OPEN.
        let mut game = room_lobby_with_control(0x1320_0032, "IDC_BUTTON_SROOM_FIRSTSTEP");
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(game.side(), Some(SideScreen::Tutorial));
        assert_eq!(game.screen(), Screen::Room);
        assert_eq!(game.room_control_noop(), None);
        assert!(game.leave_side());
        assert_eq!(game.side(), None);
        assert_eq!(game.screen(), Screen::Room);
    }

    /// Filter tabs select the list family locally (ticket #416). The
    /// 2002 parameter the exe may send on a tab press stays OPEN — no
    /// pack pins one — so this guard covers the staged-rect click and
    /// the rows the lobby paints, not a wire send.
    #[test]
    fn room_filter_tabs_keep_only_their_family_of_rows() {
        use o2jam_net::GameMode;
        let mut game = ScreenGame::new();
        let mut rooms = two_rooms();
        rooms[1].game_mode = GameMode::Live.as_u8();
        let normal_title = rooms[0].title.clone();
        let live_title = rooms[1].title.clone();
        game.set_rooms(rooms);
        game.menu_key(MenuKey::Back, true);
        game.click_planet(136, 88);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);

        let placements = [
            (0x1320_1003u32, 10),
            (0x1320_1004u32, 60),
            (0x1320_1005u32, 110),
        ]
        .into_iter()
        .map(|(code, x)| ScenePlacement {
            role: PlacementRole::Single,
            id: format!("FILTER_{code:X}"),
            code,
            sprite: None,
            rect: Rect {
                x,
                y: 10,
                w: 30,
                h: 30,
            },
        })
        .collect();
        game.load_scene(Screen::Room, placements, HashMap::new());

        game.ingest_snapshot(&InputSnapshot::click_at(75, 25));
        assert_eq!(game.room_filter(), RoomListFilter::Normal);
        let noop = game.room_control_noop().expect("the send stays OPEN");
        assert_eq!(noop.id, "IDC_BUTTON_SROOM_SHOW_NORMALMODE");
        assert!(noop.next_step.contains("2002"));
        let titles: Vec<&str> = game
            .listed_rooms()
            .iter()
            .map(|room| room.title.as_str())
            .collect();
        assert_eq!(titles, vec![normal_title.as_str()]);

        game.ingest_snapshot(&InputSnapshot::click_at(125, 25));
        assert_eq!(game.room_filter(), RoomListFilter::Live);
        let titles: Vec<&str> = game
            .listed_rooms()
            .iter()
            .map(|room| room.title.as_str())
            .collect();
        assert_eq!(titles, vec![live_title.as_str()]);

        game.ingest_snapshot(&InputSnapshot::click_at(25, 25));
        assert_eq!(game.room_filter(), RoomListFilter::All);
        assert_eq!(game.listed_rooms().len(), 2);
    }

    #[test]
    fn firststep_tutorial_exit_click_returns_to_room_and_recues_its_bgm() {
        // Live chain: boot → Planet → Channel → Room → staged FIRSTSTEP
        // click → Tutorial → bottom-right exit press → opening Room.
        // Boot1 input log `cee8b7d5…1913` clicks `(777,567)`; the next
        // frame `ed1bf56e…7b46` is the Room board with no modal.
        let mut game = ScreenGame::new();
        game.with_audio(Box::new(o2jam_audio::NullBackend::new()), HashMap::new());
        let mut bank = vec![None; 10];
        bank[2] = Some(o2jam_audio::PcmSamples {
            samples: vec![3; 441],
            sample_rate: 44_100,
            channels: 1,
        });
        game.stage_scene_bgm(bank);
        game.set_channels(two_channels());
        game.set_rooms(two_rooms());
        game.menu_key(MenuKey::Back, true);
        game.click_planet(136, 88);
        game.menu_key(MenuKey::Confirm, true);
        assert_eq!(game.screen(), Screen::Room);
        game.load_scene(
            Screen::Room,
            vec![ScenePlacement {
                role: PlacementRole::Single,
                id: "IDC_BUTTON_SROOM_FIRSTSTEP".to_owned(),
                code: 0x1320_0032,
                sprite: None,
                rect: ROOM_CONTROL_TEST_RECT,
            }],
            HashMap::new(),
        );
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(game.side(), Some(SideScreen::Tutorial));
        assert_eq!(game.scene_bgm_selection(), None, "tutorial cues silence");

        game.ingest_snapshot(&InputSnapshot::click_at(777, 567));
        assert_eq!(game.side(), None, "exit leaves the side visit");
        assert_eq!(game.screen(), Screen::Room, "opening lobby returns");
        assert_eq!(game.planet_modal(), None, "no modal on return");
        assert_eq!(game.scene_bgm_selection().map(|cue| cue.record), Some(3));
    }

