    #[test]
    fn firststep_tutorial_painter_shows_the_first_pinned_guide_frame() {
        // Live chain: boot → Planet → Channel → Room → staged FIRSTSTEP
        // click → tutorial painter. The synthetic Guide bodies carry two
        // records each: frame 0 must win (the exe's `1/13` bubble and
        // the frame-0 coach in B7, manifest `064bec85…3272d`, frame
        // `612830b5…e77b8`), never a stack of all frames.
        let mut game = room_lobby_with_control(0x1320_0032, "IDC_BUTTON_SROOM_FIRSTSTEP");
        let mut instruction = AvatarFigure::default();
        for word in [0x7C00u16, 0x03E0u16] {
            use crate::avatar::FigureLayer;
            let pixels = [word.to_le_bytes(); 16].concat();
            instruction.push_layer(FigureLayer {
                image: o2jam_render::Rgb555Image::decode(&pixels, 4, 4).unwrap(),
                dx: 374,
                dy: 297,
                colorkey: 0xFFFF,
            });
        }
        let placement = ScenePlacement {
            role: crate::avatar::PlacementRole::Single,
            id: String::new(),
            code: 0,
            sprite: Some(TUTORIAL_INSTRUCTION_SPRITE.to_owned()),
            rect: Rect {
                x: 0,
                y: 0,
                w: 800,
                h: 600,
            },
        };
        game.load_tutorial_scene(
            vec![placement],
            HashMap::from([(TUTORIAL_INSTRUCTION_SPRITE.to_owned(), instruction)]),
        );
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(game.side(), Some(SideScreen::Tutorial));
        let mut buf = vec![0u32; 800 * 600];
        game.paint_at(
            &mut Frame {
                buf: &mut buf,
                w: 800,
                h: 600,
            },
            0,
        );
        assert_eq!(buf[298 * 800 + 375], pack_xrgb(255, 0, 0));
    }

    #[test]
    fn firststep_tutorial_lane_press_lights_only_its_own_cap_with_no_judgement() {
        // Live chain: boot → Planet → Channel → Room → staged FIRSTSTEP
        // click → Tutorial → lane-key press → painter. Boot2 pack
        // `989abc137caec5cb429d98d1b0e19c094032fc1c900a350c423f6ae0e82c088f`
        // pins one lit cap per lane key with all judgement tallies at 0
        // (frames `28d1ca44…1a`, `be76f41d…3a`, `d662b505…3e`). The
        // seven kit bodies stage at their own parsed row-487 anchors.
        let mut game = room_lobby_with_control(0x1320_0032, "IDC_BUTTON_SROOM_FIRSTSTEP");
        let lit_words = [0x7C00u16, 0x03E0, 0x001F, 0x7C1F, 0x7FE0, 0x07FF, 0x681F];
        let mut placements = Vec::new();
        let mut figures = HashMap::new();
        for (lane, lit_word) in lit_words.iter().enumerate() {
            let name = format!("KeyEffect_Tutorial_{}.ojs", lane + 1);
            let mut figure = AvatarFigure::default();
            for frame in 0..5 {
                let word = if frame == 0 { 0x7FFFu16 } else { *lit_word };
                let pixels = [word.to_le_bytes(); 16].concat();
                figure.push_layer(crate::avatar::FigureLayer {
                    image: o2jam_render::Rgb555Image::decode(&pixels, 4, 4).unwrap(),
                    dx: 100 + (lane as i32) * 20,
                    dy: 487,
                    colorkey: 0x0000,
                });
            }
            placements.push(ScenePlacement {
                role: crate::avatar::PlacementRole::Single,
                id: String::new(),
                code: 0,
                sprite: Some(name.clone()),
                rect: Rect {
                    x: 0,
                    y: 0,
                    w: 800,
                    h: 600,
                },
            });
            figures.insert(name, figure);
        }
        game.load_tutorial_scene(placements, figures);
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(game.side(), Some(SideScreen::Tutorial));

        let paint = |game: &mut ScreenGame| {
            let mut buf = vec![0u32; 800 * 600];
            game.paint_at(
                &mut Frame {
                    buf: &mut buf,
                    w: 800,
                    h: 600,
                },
                0,
            );
            buf
        };
        let rest = paint(&mut game);
        let cap_pixel = |buf: &[u32], lane: usize| buf[488 * 800 + 101 + lane * 20];
        for lane in 0..7 {
            assert_eq!(cap_pixel(&rest, lane), pack_xrgb(255, 255, 255));
        }

        for lit_lane in 0..7 {
            game.lane_key(lit_lane, true);
            let pressed = paint(&mut game);
            assert_ne!(
                cap_pixel(&pressed, lit_lane),
                cap_pixel(&rest, lit_lane),
                "lane {lit_lane} cap lights"
            );
            for other_lane in (0..7).filter(|lane| *lane != lit_lane) {
                assert_eq!(
                    cap_pixel(&pressed, other_lane),
                    cap_pixel(&rest, other_lane),
                    "lane {other_lane} stays rest"
                );
            }
            assert_eq!(game.live_play().score().counts, [0, 0, 0, 0]);

            game.lane_key(lit_lane, false);
            let released = paint(&mut game);
            assert_eq!(
                cap_pixel(&released, lit_lane),
                cap_pixel(&rest, lit_lane),
                "key up clears the cap"
            );
        }
    }

    #[test]
    fn staged_room_control_without_a_target_records_a_labelled_noop() {
        // Ticket #34: `QUICKJOIN` stands in for the staged controls
        // with no evidenced target yet (`FIRSTSTEP` now enters the
        // pinned tutorial state) — the click must be recorded, never
        // silently dropped.
        let mut game = room_lobby_with_control(0x1320_0006, "IDC_BUTTON_SROOM_QUICKJOIN");
        game.ingest_snapshot(&InputSnapshot::click_at(
            ROOM_CONTROL_TEST_CLICK.0,
            ROOM_CONTROL_TEST_CLICK.1,
        ));
        assert_eq!(game.screen(), Screen::Room);
        assert_eq!(game.side(), None);
        assert_eq!(game.room_dialog(), None);
        let noop = game.room_control_noop().expect("recorded press");
        assert_eq!(noop.id, "IDC_BUTTON_SROOM_QUICKJOIN");
        // The press names the exe `CStateRoom` click dispatch rig step
        // — never a bare "unwired".
        assert!(
            noop.next_step.contains("CStateRoom click dispatch"),
            "next step names the dispatch rig step: {}",
            noop.next_step
        );
    }

    #[test]
    fn staged_firststep_rect_matches_the_room_block_rect() {
        // Install-guarded (ticket #34): the parsed 7.55 `STATE_ROOM`
        // block pairs `IDC_BUTTON_SROOM_FIRSTSTEP` (`0x13200032`) with
        // its `.bnd` rect; the click dispatch hit-tests exactly that
        // staged rect. Skips when `install-root` is absent.
        let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../install-root/O2Jam/Image/Interface1.opi");
        let Ok(bytes) = std::fs::read(&path) else {
            return;
        };
        let report = crate::staging::stage_state(
            &bytes,
            crate::staging::State::Room,
            crate::staging::StageContext::default(),
        );
        let art = report.art.expect("STATE_ROOM stages");
        let placement = art
            .placements
            .iter()
            .find(|placement| placement.code == 0x1320_0032)
            .unwrap_or_else(|| panic!("{}: FIRSTSTEP placement stages", path.display()));
        // The parsed block is the oracle (owner rule `f38f3`):
        // `GLOSSARY.md` pins FIRSTSTEP at (660,1)-(720,33); the
        // `docs/hover.md` pixel box (660,1)-(718,32) is the changed-art
        // extent, two pixels inside the rect on each axis.
        assert_eq!(
            placement.rect,
            Rect {
                x: 660,
                y: 1,
                w: 60,
                h: 32,
            },
            "FIRSTSTEP stages on its .bnd rect"
        );
    }

